    ('conduct and a teacher''s remark are written', pg_temp.t_scalar(format('with b as (insert into public.student_behavioral_assessments (enrollment_id,term_id,punctuality) select current_setting(''zz.ve'')::uuid, id, 3 from public.terms where id = %L on conflict (enrollment_id, term_id) do update set punctuality = 3 returning 1), r as (insert into public.term_remarks (school_id,enrollment_id,term_id,remark) values (%L, current_setting(''zz.ve'')::uuid, %L, ''ZZ remark'') returning 1) select ((select count(*) from b) + (select count(*) from r))::text', term, a, term)), '2'),
