    ('the class''s report is published', pg_temp.t_scalar(format('with x as (insert into public.term_report_publications (class_id,term_id,is_published) values (%L,%L,true) on conflict (class_id,term_id) do update set is_published = true returning 1) select count(*)::text from x', c1, term)), '1'),
    ('the pupil now sees both marks, even though they were hidden', pg_temp.t_try(u_s1, 'select 1 from public.scores where enrollment_id = current_setting(''zz.ve'')::uuid and score in (11.5, 7.25)'), 'ok:2'),
