    ('the principal defines a short day', pg_temp.t_try(u_prin, 'select public.save_bell_schedule(null, ''ZZ Short'', jsonb_build_array(jsonb_build_object(''label'',''Lesson 1'',''kind'',''lesson'',''start'',''08:00'',''end'',''08:30''), jsonb_build_object(''label'',''Lesson 2'',''kind'',''lesson'',''start'',''08:30'',''end'',''09:00''), jsonb_build_object(''label'',''Break'',''kind'',''break'',''start'',''09:00'',''end'',''09:15'')))'), 'ok:1'),
    ('the periods are stored in order', pg_temp.t_scalar('select string_agg(label || '' '' || to_char(starts_at,''HH24:MI'') || ''-'' || to_char(ends_at,''HH24:MI''), '', '' order by position) from public.bell_periods p join public.bell_schedules s on s.id = p.schedule_id where s.name = ''ZZ Short'''), 'Lesson 1 08:00-08:30, Lesson 2 08:30-09:00, Break 09:00-09:15'),
