    ('periods need names', (pg_temp.t_err(u_admin, 'select public.save_bell_schedule(null, ''ZZ Bad'', jsonb_build_array(jsonb_build_object(''label'','' '',''kind'',''lesson'',''start'',''08:00'',''end'',''08:40'')))') like 'TTB01: Every period needs a name.')::text, 'true'),
    ('a period is a lesson or a break', (pg_temp.t_err(u_admin, 'select public.save_bell_schedule(null, ''ZZ Bad'', jsonb_build_array(jsonb_build_object(''label'',''Lesson 1'',''kind'',''recess'',''start'',''08:00'',''end'',''08:40'')))') like 'TTB01: Each period is a lesson or a break.')::text, 'true'),
    ('a day cannot have more than 20', (pg_temp.t_err(u_admin, 'select public.save_bell_schedule(null, ''ZZ Bad'', (select jsonb_agg(jsonb_build_object(''label'',''P''||g,''kind'',''lesson'',''start'',to_char(time ''06:00'' + g * interval ''30 minutes'',''HH24:MI''),''end'',to_char(time ''06:00'' + g * interval ''30 minutes'' + interval ''25 minutes'',''HH24:MI''))) from generate_series(1,21) g))') like 'TTB01: A school day needs between 1 and 20 periods and breaks.')::text, 'true'),
    ('nothing half-saved was left behind', pg_temp.t_try(u_admin, 'select 1 from public.bell_schedules where name = ''ZZ Bad'''), 'ok:0'),
    ('two schedules cannot share a name', pg_temp.t_try(u_admin, 'select public.save_bell_schedule(null, ''ZZ Long'', jsonb_build_array(jsonb_build_object(''label'',''Lesson 1'',''kind'',''lesson'',''start'',''08:00'',''end'',''08:40''), jsonb_build_object(''label'',''Lesson 2'',''kind'',''lesson'',''start'',''08:40'',''end'',''09:20''), jsonb_build_object(''label'',''Break'',''kind'',''break'',''start'',''09:20'',''end'',''09:40''), jsonb_build_object(''label'',''Lesson 3'',''kind'',''lesson'',''start'',''09:40'',''end'',''10:20''), jsonb_build_object(''label'',''Lesson 4'',''kind'',''lesson'',''start'',''10:20'',''end'',''11:00'')))'), 'denied'),
