    ('Tuesday''s second lesson is exactly 08:40 to 09:20 and named from the schedule', pg_temp.t_scalar('select to_char(start_time,''HH24:MI'') || ''-'' || to_char(end_time,''HH24:MI'') || '' '' || label || '' '' || kind from public.timetable_slots where class_id = current_setting(''zz.t'')::uuid and day_of_week = 2 and start_time = ''08:40'''), '08:40-09:20 Lesson 2 lesson'),
