    ('Monday''s first lesson gets the first subject', pg_temp.t_scalar('select sub.name from public.timetable_slots t join public.class_subjects cs on cs.id = t.class_subject_id join public.subjects sub on sub.id = cs.subject_id where t.class_id = current_setting(''zz.t'')::uuid and t.day_of_week = 1 and t.start_time = ''08:00'''), 'ZZ TT A'),
    ('the second gets the second', pg_temp.t_scalar('select sub.name from public.timetable_slots t join public.class_subjects cs on cs.id = t.class_subject_id join public.subjects sub on sub.id = cs.subject_id where t.class_id = current_setting(''zz.t'')::uuid and t.day_of_week = 1 and t.start_time = ''08:30'''), 'ZZ TT B'),
    ('and Tuesday''s first carries on with the third', pg_temp.t_scalar('select sub.name from public.timetable_slots t join public.class_subjects cs on cs.id = t.class_subject_id join public.subjects sub on sub.id = cs.subject_id where t.class_id = current_setting(''zz.t'')::uuid and t.day_of_week = 2 and t.start_time = ''08:00'''), 'ZZ TT C'),
    ('breaks were left alone', pg_temp.t_scalar('select count(*)::text from public.timetable_slots where class_id = current_setting(''zz.t'')::uuid and kind = ''break'' and class_subject_id is not null'), '0'),
    ('filling again fills nothing', pg_temp.t_val(u_admin, 'select public.fill_class_subjects(current_setting(''zz.t'')::uuid)::text'), '0'),
    ('reapplying the school day keeps every subject', pg_temp.t_val(u_admin, 'select public.apply_bell_schedule(current_setting(''zz.t'')::uuid)::text'), '{"created": 0, "removed": 0, "offSchedule": 0}'),
    ('Tuesday''s first lesson still has its subject', pg_temp.t_scalar('select sub.name from public.timetable_slots t join public.class_subjects cs on cs.id = t.class_subject_id join public.subjects sub on sub.id = cs.subject_id where t.class_id = current_setting(''zz.t'')::uuid and t.day_of_week = 2 and t.start_time = ''08:00'''), 'ZZ TT C'),
    ('the admin lengthens the second lesson and moves the later ones', pg_temp.t_try(u_admin, 'select public.save_bell_schedule((select id from public.bell_schedules where name = ''ZZ Long''), ''ZZ Long'', jsonb_build_array(jsonb_build_object(''label'',''Lesson 1'',''kind'',''lesson'',''start'',''08:00'',''end'',''08:40''), jsonb_build_object(''label'',''Lesson 2'',''kind'',''lesson'',''start'',''08:40'',''end'',''09:30''), jsonb_build_object(''label'',''Break'',''kind'',''break'',''start'',''09:30'',''end'',''09:50''), jsonb_build_object(''label'',''Lesson 3'',''kind'',''lesson'',''start'',''09:50'',''end'',''10:30''), jsonb_build_object(''label'',''Lesson 4'',''kind'',''lesson'',''start'',''10:30'',''end'',''11:10'')))'), 'ok:1'),
    ('reapplying: the new break and two new lessons appear, the old empty break goes, and the old lessons that hold subjects are kept and counted', pg_temp.t_val(u_admin, 'select public.apply_bell_schedule(current_setting(''zz.t'')::uuid)::text'), '{"created": 9, "removed": 3, "offSchedule": 6}'),
    ('the second lesson now ends at 09:30 and kept its subject', pg_temp.t_scalar('select to_char(end_time,''HH24:MI'') || '' '' || (class_subject_id is not null)::text from public.timetable_slots where class_id = current_setting(''zz.t'')::uuid and day_of_week = 2 and start_time = ''08:40'''), '09:30 true'),
    ('the new third lesson is empty', pg_temp.t_scalar('select (class_subject_id is null)::text from public.timetable_slots where class_id = current_setting(''zz.t'')::uuid and day_of_week = 2 and start_time = ''09:50'''), 'true'),
    ('the old third lesson is still there with its subject', pg_temp.t_scalar('select (class_subject_id is not null)::text from public.timetable_slots where class_id = current_setting(''zz.t'')::uuid and day_of_week = 2 and start_time = ''09:40'''), 'true'),
    ('Monday and Friday were not touched', pg_temp.t_scalar('select count(*)::text from public.timetable_slots where class_id = current_setting(''zz.t'')::uuid and day_of_week = 1') || '/' || pg_temp.t_scalar('select count(*)::text from public.timetable_slots where class_id = current_setting(''zz.t'')::uuid and day_of_week = 5'), '3/3'),
    ('a teacher cannot apply it to every class', (pg_temp.t_val(u_t1, 'select public.apply_bell_schedule_to_all()::text') like '42501: not allowed')::text, 'true'),
    ('the admin can', (pg_temp.t_err(u_admin, 'select public.apply_bell_schedule_to_all()') = 'ok')::text, 'true'),
    ('a schedule in use cannot be deleted', (pg_temp.t_err(u_admin, 'select public.delete_bell_schedule((select id from public.bell_schedules where name = ''ZZ Short''))') like 'TTB01: Some days still use this schedule.%')::text, 'true'),
    ('the admin takes day 1 off the long day', pg_temp.t_try(u_admin, 'select public.set_bell_assignment(null, 1, null)'), 'ok:1'),
    ('the admin takes day 2 off the long day', pg_temp.t_try(u_admin, 'select public.set_bell_assignment(null, 2, null)'), 'ok:1'),
    ('the admin takes day 3 off the long day', pg_temp.t_try(u_admin, 'select public.set_bell_assignment(null, 3, null)'), 'ok:1'),
    ('the admin takes day 4 off the long day', pg_temp.t_try(u_admin, 'select public.set_bell_assignment(null, 4, null)'), 'ok:1'),
    ('and Friday off the short day', pg_temp.t_try(u_admin, 'select public.set_bell_assignment(null, 5, null)'), 'ok:1'),
    ('and the level''s Monday', pg_temp.t_try(u_admin, format('select public.set_bell_assignment(%L, 1, null)', lvl)), 'ok:1'),
    ('a day with no schedule is left alone when applied', pg_temp.t_val(u_admin, 'select public.apply_bell_schedule(current_setting(''zz.t'')::uuid)::text'), '{"created": 0, "removed": 0, "offSchedule": 0}'),
    ('the unused short day can now be deleted', pg_temp.t_try(u_admin, 'select public.delete_bell_schedule((select id from public.bell_schedules where name = ''ZZ Short''))'), 'ok:1'),
    ('and its periods went with it', pg_temp.t_scalar('select count(*)::text from public.bell_periods p where p.label = ''Lesson 2'' and p.ends_at = ''09:00'''), '0'),
    ('the admin switches the timetable off', pg_temp.t_try(u_admin, 'select public.set_school_features((select array_agg(key) from public.app_features where key <> ''timetable''))'), 'ok:1'),
    ('so the schedules disappear', pg_temp.t_try(u_admin, 'select 1 from public.bell_schedules where name like ''ZZ%'''), 'ok:0'),
    ('and nobody can define a day', pg_temp.t_try(u_admin, 'select public.save_bell_schedule(null, ''ZZ Off'', jsonb_build_array(jsonb_build_object(''label'',''Lesson 1'',''kind'',''lesson'',''start'',''08:00'',''end'',''08:40''), jsonb_build_object(''label'',''Lesson 2'',''kind'',''lesson'',''start'',''08:40'',''end'',''09:20''), jsonb_build_object(''label'',''Break'',''kind'',''break'',''start'',''09:20'',''end'',''09:40''), jsonb_build_object(''label'',''Lesson 3'',''kind'',''lesson'',''start'',''09:40'',''end'',''10:20''), jsonb_build_object(''label'',''Lesson 4'',''kind'',''lesson'',''start'',''10:20'',''end'',''11:00'')))'), 'denied'),
    ('the admin switches everything back on', pg_temp.t_try(u_admin, format('select public.set_school_features(%s)', '(select array_agg(key) from public.app_features)')), 'ok:1'),
    ('a developer holds the action', pg_temp.t_try(u_dev, 'select 1 where public.has_capability(''timetable.manage_schedule'')'), 'ok:1'),
    ('a teacher does not', pg_temp.t_try(u_t1, 'select 1 where public.has_capability(''timetable.manage_schedule'')'), 'ok:0'),
    -- Tasks and duties
    ('a teacher cannot assign a task', pg_temp.t_try(u_t1, format('select public.save_task(null, ''ZZ Gate duty'', ''Open the gate'', ''duty'', current_date + 3, current_date + 3, ''07:30'', ''08:00'', ''Main gate'', null, array[%L, %L]::uuid[])', u_t1, u_rec)), 'denied'),
    ('a parent cannot', pg_temp.t_try(u_p1, format('select public.save_task(null, ''ZZ Gate duty'', ''Open the gate'', ''duty'', current_date + 3, current_date + 3, ''07:30'', ''08:00'', ''Main gate'', null, array[%L, %L]::uuid[])', u_t1, u_rec)), 'denied'),
    ('HR, who sees everyone''s tasks, cannot assign', pg_temp.t_try(u_hr, format('select public.save_task(null, ''ZZ Gate duty'', ''Open the gate'', ''duty'', current_date + 3, current_date + 3, ''07:30'', ''08:00'', ''Main gate'', null, array[%L, %L]::uuid[])', u_t1, u_rec)), 'denied'),
    ('the admin gives two members of staff a gate duty', pg_temp.t_try(u_admin, format('select public.save_task(null, ''ZZ Gate duty'', ''Open the gate'', ''duty'', current_date + 3, current_date + 3, ''07:30'', ''08:00'', ''Main gate'', null, array[%L, %L]::uuid[])', u_t1, u_rec)), 'ok:1'),
    ('the first teacher sees it', pg_temp.t_try(u_t1, 'select 1 from public.tasks where title = ''ZZ Gate duty'''), 'ok:1'),
    ('so does reception', pg_temp.t_try(u_rec, 'select 1 from public.tasks where title = ''ZZ Gate duty'''), 'ok:1'),
    ('the accountant, who is not on it, does not', pg_temp.t_try(u_acc, 'select 1 from public.tasks where title = ''ZZ Gate duty'''), 'ok:0'),
    ('HR sees every task', pg_temp.t_try(u_hr, 'select 1 from public.tasks where title = ''ZZ Gate duty'''), 'ok:1'),
    ('the principal sees every task', pg_temp.t_try(u_prin, 'select 1 from public.tasks where title = ''ZZ Gate duty'''), 'ok:1'),
    ('the admin does', pg_temp.t_try(u_admin, 'select 1 from public.tasks where title = ''ZZ Gate duty'''), 'ok:1'),
    ('a parent does not', pg_temp.t_try(u_p1, 'select 1 from public.tasks where title = ''ZZ Gate duty'''), 'ok:0'),
    ('a student does not', pg_temp.t_try(u_s1, 'select 1 from public.tasks where title = ''ZZ Gate duty'''), 'ok:0'),
    ('another school''s admin does not', pg_temp.t_try(u_adminb, 'select 1 from public.tasks where title = ''ZZ Gate duty'''), 'ok:0'),
    ('a teacher sees only their own part of it', pg_temp.t_try(u_t1, 'select 1 from public.task_assignees a join public.tasks t on t.id = a.task_id where t.title = ''ZZ Gate duty'''), 'ok:1'),
    ('the admin sees both people', pg_temp.t_try(u_admin, 'select 1 from public.task_assignees a join public.tasks t on t.id = a.task_id where t.title = ''ZZ Gate duty'''), 'ok:2'),
    ('each person was told', pg_temp.t_try(u_t1, 'select 1 from public.notifications where title = ''New task: ZZ Gate duty'''), 'ok:1'),
    ('the notice says when and where', pg_temp.t_try(u_t1, 'select 1 from public.notifications where title = ''New task: ZZ Gate duty'' and body like ''%07:30 at Main gate'''), 'ok:1'),
    ('the admin who assigned it is not told', pg_temp.t_try(u_admin, 'select 1 from public.notifications where title = ''New task: ZZ Gate duty'''), 'ok:0'),
    ('the teacher ticks their part off', pg_temp.t_val(u_t1, format('select public.set_my_task_status((select id from public.tasks where title = ''ZZ Gate duty''), true)::text')), '1'),
    ('the time is stamped', pg_temp.t_scalar('select (done_at is not null)::text from public.task_assignees a join public.tasks t on t.id = a.task_id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Gate duty'' and p.full_name = ''teacher1'''), 'true'),
    ('reception''s part is still open', pg_temp.t_scalar('select a.status from public.task_assignees a join public.tasks t on t.id = a.task_id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Gate duty'' and p.full_name = ''reception'''), 'todo'),
    ('a teacher cannot tick off someone else''s part', pg_temp.t_try(u_t1, format('update public.task_assignees set status = ''done'' where profile_id = %L', u_rec)), 'ok:0'),
    ('or through the call', pg_temp.t_val(u_acc, format('select public.set_my_task_status((select id from public.tasks where title = ''ZZ Gate duty''), true)::text')), '0'),
    ('a teacher cannot change who the part belongs to', pg_temp.t_try(u_t1, format('update public.task_assignees set profile_id = %L where profile_id = %L', u_acc, u_t1)), 'denied'),
    ('or backdate the time', pg_temp.t_try(u_t1, 'update public.task_assignees set done_at = ''2020-01-01'' where status = ''done'''), 'denied'),
    ('the admin can tick for someone', pg_temp.t_try(u_admin, format('update public.task_assignees set status = ''done'' where profile_id = %L', u_rec)), 'ok:1'),
    ('and the teacher reopens their own', pg_temp.t_val(u_t1, format('select public.set_my_task_status((select id from public.tasks where title = ''ZZ Gate duty''), false)::text')), '1'),
    ('which clears the time', pg_temp.t_scalar('select (done_at is null)::text from public.task_assignees a join public.profiles p on p.id = a.profile_id join public.tasks t on t.id = a.task_id where t.title = ''ZZ Gate duty'' and p.full_name = ''teacher1'''), 'true'),
    ('a teacher cannot edit a task', pg_temp.t_try(u_t1, 'update public.tasks set title = ''Hacked'' where title = ''ZZ Gate duty'''), 'ok:0'),
    ('or remove it', pg_temp.t_try(u_t1, 'delete from public.tasks where title = ''ZZ Gate duty'''), 'ok:0'),
    ('a parent cannot be given a task', (pg_temp.t_err(u_admin, format('select public.save_task(null, ''ZZ Nope'', null, ''duty'', current_date, current_date, null, null, null, null, array[%L]::uuid[])', u_p1)) like 'TSK01: Tasks can only be given to active staff.')::text, 'true'),
    ('nor a student', (pg_temp.t_err(u_admin, format('select public.save_task(null, ''ZZ Nope'', null, ''duty'', current_date, current_date, null, null, null, null, array[%L]::uuid[])', u_s1)) like 'TSK01: Tasks can only be given to active staff.')::text, 'true'),
    ('nor someone deactivated', (pg_temp.t_err(u_admin, format('select public.save_task(null, ''ZZ Nope'', null, ''duty'', current_date, current_date, null, null, null, null, array[%L]::uuid[])', u_off)) like 'TSK01: Tasks can only be given to active staff.')::text, 'true'),
    ('nor someone from another school', (pg_temp.t_err(u_admin, format('select public.save_task(null, ''ZZ Nope'', null, ''duty'', current_date, current_date, null, null, null, null, array[%L]::uuid[])', u_adminb)) like 'TSK01: Tasks can only be given to active staff.')::text, 'true'),
    ('a refused task leaves nothing behind', pg_temp.t_try(u_admin, 'select 1 from public.tasks where title = ''ZZ Nope'''), 'ok:0'),
    ('a task needs a title', (pg_temp.t_err(u_admin, format('select public.save_task(null, ''  '', null, ''duty'', current_date, current_date, null, null, null, null, array[%L]::uuid[])', u_t1)) like 'TSK01: Give the task a title.')::text, 'true'),
    ('and someone to do it', (pg_temp.t_err(u_admin, 'select public.save_task(null, ''ZZ Nope'', null, ''duty'', current_date, current_date, null, null, null, null, array[]::uuid[])') like 'TSK01: Choose between 1 and 30 people.')::text, 'true'),
    ('it cannot end before it starts', (pg_temp.t_err(u_admin, format('select public.save_task(null, ''ZZ Nope'', null, ''duty'', current_date + 2, current_date, null, null, null, null, array[%L]::uuid[])', u_t1)) like '23514%')::text, 'true'),
    ('an end time needs a start time', (pg_temp.t_err(u_admin, format('select public.save_task(null, ''ZZ Nope'', null, ''duty'', current_date, current_date, null, ''09:00'', null, null, array[%L]::uuid[])', u_t1)) like '23514%')::text, 'true'),
    ('the kind must be known', (pg_temp.t_err(u_admin, format('select public.save_task(null, ''ZZ Nope'', null, ''party'', current_date, current_date, null, null, null, null, array[%L]::uuid[])', u_t1)) like '23514%')::text, 'true'),
    ('an exam period that does not exist is refused', (pg_temp.t_err(u_admin, format('select public.save_task(null, ''ZZ Nope'', null, ''invigilation'', current_date, current_date, null, null, null, gen_random_uuid(), array[%L]::uuid[])', u_t1)) like 'TSK01: That exam period was not found.')::text, 'true'),
    ('a real exam period can be linked', pg_temp.t_try(u_prin, format('insert into public.exam_periods (term_id,name,kind,starts_on,ends_on) values (%L,''ZZ Task Exam'',''mock'',current_date + 10,current_date + 12)', term)), 'ok:1'),
    ('an invigilation task points at it', pg_temp.t_try(u_admin, 'select 1 where public.save_task(null, ''ZZ Invigilate'', null, ''invigilation'', current_date + 10, current_date + 12, ''09:00'', ''11:00'', ''Hall'', (select id from public.exam_periods where name = ''ZZ Task Exam''), array[(select id from public.profiles where full_name = ''accountant'')]::uuid[]) is not null'), 'ok:1'),
    ('and is linked', pg_temp.t_scalar('select (exam_period_id is not null)::text from public.tasks where title = ''ZZ Invigilate'''), 'true'),
    ('the admin swaps reception for the accountant', pg_temp.t_try(u_admin, format('select public.save_task((select id from public.tasks where title = ''ZZ Gate duty''), ''ZZ Gate duty'', ''Open the gate'', ''duty'', current_date + 3, current_date + 3, ''07:30'', ''08:00'', ''Main gate'', null, array[%L, %L]::uuid[])', u_t1, u_acc)), 'ok:1'),
    ('reception no longer sees it', pg_temp.t_try(u_rec, 'select 1 from public.tasks where title = ''ZZ Gate duty'''), 'ok:0'),
    ('the accountant now does', pg_temp.t_try(u_acc, 'select 1 from public.tasks where title = ''ZZ Gate duty'''), 'ok:1'),
    ('the teacher is still on it, unticked as they left it', pg_temp.t_scalar('select a.status from public.task_assignees a join public.tasks t on t.id = a.task_id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Gate duty'' and p.full_name = ''teacher1'''), 'todo'),
    ('the new person was told', pg_temp.t_try(u_acc, 'select 1 from public.notifications where title = ''New task: ZZ Gate duty'''), 'ok:1'),
    ('the person who stayed was not told again', pg_temp.t_try(u_t1, 'select 1 from public.notifications where title = ''New task: ZZ Gate duty'''), 'ok:1'),
    ('the admin can list the staff to choose from', (pg_temp.t_val(u_admin, 'select (count(*) >= 5)::text from public.assignable_staff()')), 'true'),
    ('parents and students are not in it', pg_temp.t_val(u_admin, 'select count(*)::text from public.assignable_staff() where full_name in (''parent1'', ''parent2'', ''student1'', ''deactivated'')'), '0'),
    ('HR may see the list', (pg_temp.t_val(u_hr, 'select (count(*) >= 5)::text from public.assignable_staff()')), 'true'),
    ('a teacher may not', (pg_temp.t_val(u_t1, 'select count(*)::text from public.assignable_staff()') like '42501%')::text, 'true'),
    ('a teacher cannot make a rota', pg_temp.t_try(u_t1, format('select public.save_task_rota(null, ''ZZ Morning gate'', null, ''duty'', array[1,2,3,4,5], null, null, ''Main gate'', ''weekly'', 1, (date_trunc(''week'', current_date)::date + 14), (date_trunc(''week'', current_date)::date + 14) + 18, array[%L, %L, %L]::uuid[])', u_t1, u_rec, u_acc)), 'denied'),
    ('HR cannot', pg_temp.t_try(u_hr, format('select public.save_task_rota(null, ''ZZ Morning gate'', null, ''duty'', array[1,2,3,4,5], null, null, ''Main gate'', ''weekly'', 1, (date_trunc(''week'', current_date)::date + 14), (date_trunc(''week'', current_date)::date + 14) + 18, array[%L, %L, %L]::uuid[])', u_t1, u_rec, u_acc)), 'denied'),
    ('the admin makes a weekly gate rota over three weeks', pg_temp.t_try(u_admin, format('select public.save_task_rota(null, ''ZZ Morning gate'', null, ''duty'', array[1,2,3,4,5], null, null, ''Main gate'', ''weekly'', 1, (date_trunc(''week'', current_date)::date + 14), (date_trunc(''week'', current_date)::date + 14) + 18, array[%L, %L, %L]::uuid[])', u_t1, u_rec, u_acc)), 'ok:1'),
    ('HR can read it', pg_temp.t_try(u_hr, 'select 1 from public.task_rotas where title = ''ZZ Morning gate'''), 'ok:1'),
    ('a teacher cannot', pg_temp.t_try(u_t1, 'select 1 from public.task_rotas where title = ''ZZ Morning gate'''), 'ok:0'),
    ('a teacher cannot generate it', (pg_temp.t_val(u_t1, 'select public.generate_rota_tasks((select id from public.task_rotas where title = ''ZZ Morning gate''))::text') like '42501%')::text, 'true'),
    ('the admin generates fifteen days of duty', pg_temp.t_val(u_admin, 'select public.generate_rota_tasks((select id from public.task_rotas where title = ''ZZ Morning gate''))::text'), '15'),
    ('week one is the first person, every day', pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Morning gate'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 0') || '/' || pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Morning gate'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 4'), 'teacher1/teacher1'),
    ('week two is the second', pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Morning gate'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 7') || '/' || pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Morning gate'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 11'), 'reception/reception'),
    ('week three is the third', pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Morning gate'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 14'), 'accountant'),
    ('the first person has five days', pg_temp.t_scalar(format('select count(*)::text from public.tasks t join public.task_assignees a on a.task_id = t.id where t.title = ''ZZ Morning gate'' and a.profile_id = %L', u_t1)), '5'),
    ('the second has five', pg_temp.t_scalar(format('select count(*)::text from public.tasks t join public.task_assignees a on a.task_id = t.id where t.title = ''ZZ Morning gate'' and a.profile_id = %L', u_rec)), '5'),
    ('the third has five', pg_temp.t_scalar(format('select count(*)::text from public.tasks t join public.task_assignees a on a.task_id = t.id where t.title = ''ZZ Morning gate'' and a.profile_id = %L', u_acc)), '5'),
    ('the weekend is left out', pg_temp.t_scalar('select count(*)::text from public.tasks where title = ''ZZ Morning gate'' and extract(isodow from starts_on) > 5'), '0'),
