    ('saying how many', pg_temp.t_try(u_t1, 'select 1 from public.notifications where title = ''New rota duties: ZZ Morning gate'' and body like ''You have 5 new duties from %'''), 'ok:1'),
    ('and no note for each day', pg_temp.t_try(u_t1, 'select 1 from public.notifications where title = ''New task: ZZ Morning gate'''), 'ok:0'),
    ('a rota''s day is on the person''s own list', pg_temp.t_try(u_rec, 'select 1 from public.tasks where title = ''ZZ Morning gate'''), 'ok:5'),
    ('the first person ticks off day two', pg_temp.t_val(u_t1, format('select public.set_my_task_status((select t.id from public.tasks t where t.title = ''ZZ Morning gate'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 1), true)::text')), '1'),
    ('the admin reorders the people', pg_temp.t_try(u_admin, format('select public.save_task_rota((select id from public.task_rotas where title = ''ZZ Morning gate''), ''ZZ Morning gate'', null, ''duty'', array[1,2,3,4,5], null, null, ''Main gate'', ''weekly'', 1, (date_trunc(''week'', current_date)::date + 14), (date_trunc(''week'', current_date)::date + 14) + 18, array[%L, %L, %L]::uuid[])', u_rec, u_t1, u_acc)), 'ok:1'),
    ('and generates again, which remakes only what was not ticked off', pg_temp.t_val(u_admin, 'select public.generate_rota_tasks((select id from public.task_rotas where title = ''ZZ Morning gate''))::text'), '14'),
    ('there are still fifteen days', pg_temp.t_scalar('select count(*)::text from public.tasks where title = ''ZZ Morning gate'''), '15'),
    ('the ticked day kept its first person', pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Morning gate'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 1'), 'teacher1'),
    ('the other days of week one now go to the new first person', pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Morning gate'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 0'), 'reception'),
    ('week two goes to the second', pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Morning gate'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 7'), 'teacher1'),
    ('a daily rota gives two people a day in turn', pg_temp.t_try(u_admin, format('select public.save_task_rota(null, ''ZZ Playground'', null, ''duty'', array[1,3], null, null, ''Field'', ''daily'', 2, (date_trunc(''week'', current_date)::date + 14), (date_trunc(''week'', current_date)::date + 14) + 11, array[%L, %L, %L]::uuid[])', u_t1, u_rec, u_acc)), 'ok:1'),
    ('four days are made', pg_temp.t_val(u_admin, 'select public.generate_rota_tasks((select id from public.task_rotas where title = ''ZZ Playground''))::text'), '4'),
    ('day one is the first and second person', pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Playground'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 0'), 'reception,teacher1'),
    ('day two moves on to the third and wraps to the first', pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Playground'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 2'), 'accountant,teacher1'),
    ('day three is the second and third', pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Playground'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 7'), 'accountant,reception'),
    ('day four wraps round again', pg_temp.t_scalar('select coalesce(string_agg(p.full_name, '','' order by p.full_name), ''nobody'') from public.tasks t join public.task_assignees a on a.task_id = t.id join public.profiles p on p.id = a.profile_id where t.title = ''ZZ Playground'' and t.starts_on = (date_trunc(''week'', current_date)::date + 14) + 9'), 'reception,teacher1'),
    ('more people a day than are in the rota is refused', (pg_temp.t_err(u_admin, 'select public.save_task_rota(null, ''ZZ Nope'', null, ''duty'', array[1], null, null, null, ''daily'', 3, current_date, current_date + 7, array[(select id from public.profiles where full_name = ''teacher1'')]::uuid[])') like 'TSK01: You cannot put more people on a day than are in the rota.')::text, 'true'),
    ('Saturday is not a rota day', (pg_temp.t_err(u_admin, 'select public.save_task_rota(null, ''ZZ Nope'', null, ''duty'', array[6], null, null, null, ''daily'', 1, current_date, current_date + 7, array[(select id from public.profiles where full_name = ''teacher1'')]::uuid[])') like '23514%')::text, 'true'),
    ('a rota with someone who is not staff cannot be generated', (pg_temp.t_val(u_admin, format('select public.generate_rota_tasks(public.save_task_rota(null, ''ZZ Bad rota'', null, ''duty'', array[1], null, null, null, ''daily'', 1, (date_trunc(''week'', current_date)::date + 14), (date_trunc(''week'', current_date)::date + 14) + 7, array[%L]::uuid[]))::text', u_p1)) like 'TSK01: Someone in this rota is no longer active staff.%')::text, 'true'),
    ('and that rota made nothing', pg_temp.t_scalar('select count(*)::text from public.tasks where title = ''ZZ Bad rota'''), '0'),
    ('the admin removes the playground rota', pg_temp.t_try(u_admin, 'select public.delete_task_rota((select id from public.task_rotas where title = ''ZZ Playground''))'), 'ok:1'),
    ('its days ahead go with it', pg_temp.t_scalar('select count(*)::text from public.tasks where title = ''ZZ Playground'''), '0'),
    ('removing the gate rota keeps the ticked-off day as history', pg_temp.t_try(u_admin, 'select public.delete_task_rota((select id from public.task_rotas where title = ''ZZ Morning gate''))'), 'ok:1'),
    ('only the ticked day remains', pg_temp.t_scalar('select count(*)::text from public.tasks where title = ''ZZ Morning gate'''), '1'),
    ('with no rota behind it', pg_temp.t_scalar('select (rota_id is null)::text from public.tasks where title = ''ZZ Morning gate'''), 'true'),
    ('the admin switches tasks off', pg_temp.t_try(u_admin, 'select public.set_school_features((select array_agg(key) from public.app_features where key <> ''tasks''))'), 'ok:1'),
    ('the teacher sees no tasks', pg_temp.t_try(u_t1, 'select 1 from public.tasks'), 'ok:0'),
    ('nor does the admin', pg_temp.t_try(u_admin, 'select 1 from public.tasks'), 'ok:0'),
    ('and nobody can assign', (pg_temp.t_err(u_admin, format('select public.save_task(null, ''ZZ Off'', null, ''duty'', current_date, current_date, null, null, null, null, array[%L]::uuid[])', u_t1)) like '42501%')::text, 'true'),
    ('the admin switches everything back on', pg_temp.t_try(u_admin, format('select public.set_school_features(%s)', '(select array_agg(key) from public.app_features)')), 'ok:1'),
    ('a teacher can see and tick off their own', pg_temp.t_try(u_t1, 'select 1 where public.has_capability(''tasks.view_own'')'), 'ok:1'),
    ('but not see everyone''s', pg_temp.t_try(u_t1, 'select 1 where public.has_capability(''tasks.view_all'')'), 'ok:0'),
    ('HR can download the list', pg_temp.t_try(u_hr, 'select 1 where public.has_capability(''tasks.download'')'), 'ok:1'),
    ('a teacher cannot', pg_temp.t_try(u_t1, 'select 1 where public.has_capability(''tasks.download'')'), 'ok:0'),
    ('a developer holds every task action', pg_temp.t_try(u_dev, 'select 1 where public.has_capability(''tasks.assign'') and public.has_capability(''tasks.view_all'') and public.has_capability(''tasks.download'')'), 'ok:1'),
    -- Syllabus and lesson plans
    ('a class in the current year, taught by the first teacher', pg_temp.t_scalar(format('with y as (select id from public.academic_years where is_current limit 1), c as (insert into public.classes (school_id,level_id,academic_year_id,section,class_teacher_id) select %L, %L, y.id, ''ZLP'', %L from y returning id), x as (insert into public.class_subjects (school_id,class_id,subject_id,teacher_id) select %L, c.id, %L, %L from c returning id) select set_config(''zz.lcs'', (select id::text from x), true) is not null', a, lvl, t1, a, subj, t1)), 'true'),
    ('a class subject for the other class, taught by someone else', pg_temp.t_scalar(format('with x as (insert into public.class_subjects (school_id,class_id,subject_id,teacher_id) values (%L,%L,%L,%L) returning id) select set_config(''zz.cs2'', (select id::text from x), true) is not null', a, c2, subj, t2)), 'true'),
    ('the period the school is in starts on a Monday', pg_temp.t_scalar('select set_config(''zz.p0'', public._plan_period_start((select school_id from public.profiles where full_name = ''teacher1''), current_date)::text, true) is not null'), 'true'),
    ('a Monday', pg_temp.t_scalar('select (extract(isodow from current_setting(''zz.p0'')::date) = 1)::text'), 'true'),
    ('plans cover one week by default', pg_temp.t_val(u_t1, 'select public.lesson_plan_schedule()->>''periodWeeks'''), '1'),
    ('and are due on Friday', pg_temp.t_val(u_t1, 'select public.lesson_plan_schedule()->>''dueWeekday'''), '5'),
    ('and are reviewed', pg_temp.t_val(u_t1, 'select public.lesson_plan_schedule()->>''requireReview'''), 'true'),
    ('the current period is a week long', pg_temp.t_val(u_t1, 'select (((public.lesson_plan_schedule()->''current''->>''end'')::date - (public.lesson_plan_schedule()->''current''->>''start'')::date) = 6)::text'), 'true'),
    ('plans for the next period are due the Friday before it begins (3 days earlier)', pg_temp.t_val(u_t1, 'select (((public.lesson_plan_schedule()->''next''->>''start'')::date - (public.lesson_plan_schedule()->''next''->>''dueOn'')::date) = 3)::text'), 'true'),
    ('the next period starts a week after this one', pg_temp.t_val(u_t1, 'select (((public.lesson_plan_schedule()->''next''->>''start'')::date - (public.lesson_plan_schedule()->''current''->>''start'')::date) = 7)::text'), 'true'),
    ('a parent cannot ask', (pg_temp.t_val(u_p1, 'select public.lesson_plan_schedule()::text') like '42501%')::text, 'true'),
    ('a teacher cannot change the rules', (pg_temp.t_val(u_t1, 'select public.save_lesson_plan_settings(2, 3, false)::text') like '42501%')::text, 'true'),
    ('a plan cannot cover 13 weeks', (pg_temp.t_err(u_admin, 'select public.save_lesson_plan_settings(13, 5, true)') = 'LPN01: A plan can cover between 1 and 12 weeks.')::text, 'true'),
    ('nor be due on day 8', (pg_temp.t_err(u_admin, 'select public.save_lesson_plan_settings(1, 8, true)') = 'LPN01: Choose a day of the week.')::text, 'true'),
    ('a teacher cannot add a syllabus topic', pg_temp.t_try(u_t1, format('insert into public.syllabus_topics (subject_id,level_id,title) values (%L,%L,''ZZ Hacked'')', subj, lvl)), 'denied'),
    ('the admin adds a topic for a subject and level', pg_temp.t_try(u_admin, format('insert into public.syllabus_topics (subject_id,level_id,title,term_no,week_no,position,objectives) values (%L,%L,''ZZ Fractions'',1,2,1,''Understand fractions'')', subj, lvl)), 'ok:1'),
    ('a teacher can read the syllabus', pg_temp.t_try(u_t1, 'select 1 from public.syllabus_topics where title like ''ZZ%'''), 'ok:1'),
    ('HR can too', pg_temp.t_try(u_hr, 'select 1 from public.syllabus_topics where title like ''ZZ%'''), 'ok:1'),
    ('reception cannot', pg_temp.t_try(u_rec, 'select 1 from public.syllabus_topics where title like ''ZZ%'''), 'ok:0'),
    ('a parent cannot', pg_temp.t_try(u_p1, 'select 1 from public.syllabus_topics where title like ''ZZ%'''), 'ok:0'),
    ('another school cannot', pg_temp.t_try(u_adminb, 'select 1 from public.syllabus_topics where title like ''ZZ%'''), 'ok:0'),
    ('a teacher cannot change a topic', pg_temp.t_try(u_t1, 'update public.syllabus_topics set title = ''ZZ Hacked'' where title = ''ZZ Fractions'''), 'ok:0'),
    ('or remove one', pg_temp.t_try(u_t1, 'delete from public.syllabus_topics where title = ''ZZ Fractions'''), 'ok:0'),
    ('a term must be 1 to 3', pg_temp.t_try(u_admin, format('insert into public.syllabus_topics (subject_id,level_id,title,term_no) values (%L,%L,''ZZ Bad'',4)', subj, lvl)), 'denied'),
    ('a topic needs a title', pg_temp.t_try(u_admin, format('insert into public.syllabus_topics (subject_id,level_id,title) values (%L,%L,''   '')', subj, lvl)), 'denied'),
    ('the admin imports three topics after the first', pg_temp.t_val(u_admin, format('select public.import_syllabus_topics(%L, %L, ' || quote_literal('[{"term":1,"week":3,"title":"ZZ Decimals","objectives":"Read decimals"},{"term":2,"title":"ZZ Shapes"},{"title":"ZZ Measures"}]') || '::jsonb, false)::text', subj, lvl)), '3'),
    ('so there are four, in order', pg_temp.t_scalar('select string_agg(title, '','' order by position) from public.syllabus_topics where title like ''ZZ%'''), 'ZZ Fractions,ZZ Decimals,ZZ Shapes,ZZ Measures'),
    ('a teacher cannot import', (pg_temp.t_val(u_t1, format('select public.import_syllabus_topics(%L, %L, ' || quote_literal('[{"title":"ZZ x"}]') || '::jsonb, false)::text', subj, lvl)) like '42501%')::text, 'true'),
    ('a blank title in an import refuses all of it', (pg_temp.t_val(u_admin, format('select public.import_syllabus_topics(%L, %L, ' || quote_literal('[{"title":"ZZ ok"},{"title":" "}]') || '::jsonb, false)::text', subj, lvl)) like 'LPN01: Every topic needs a title%')::text, 'true'),
    ('and none of it was added', pg_temp.t_scalar('select count(*)::text from public.syllabus_topics where title = ''ZZ ok'''), '0'),
    ('an import needs at least one topic', (pg_temp.t_val(u_admin, format('select public.import_syllabus_topics(%L, %L, ' || quote_literal('[]') || '::jsonb, false)::text', subj, lvl)) like 'LPN01: Import between 1 and 300 topics at a time.')::text, 'true'),
    ('an unknown subject is refused', (pg_temp.t_val(u_admin, format('select public.import_syllabus_topics(gen_random_uuid(), %L, ' || quote_literal('[{"title":"ZZ x"}]') || '::jsonb, false)::text', lvl)) like 'LPN01: That subject or level was not found.')::text, 'true'),
    ('a parent cannot write a plan', (pg_temp.t_err(u_p1, 'select public.save_lesson_plan(null, current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date, null, ''ZZ Fractions'', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 5'', null)') like '42501%')::text, 'true'),
    ('reception cannot', (pg_temp.t_err(u_rec, 'select public.save_lesson_plan(null, current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date, null, ''ZZ Fractions'', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 5'', null)') like '42501%')::text, 'true'),
    ('a teacher cannot plan for a class they do not teach', (pg_temp.t_err(u_t1, 'select public.save_lesson_plan(null, current_setting(''zz.cs2'')::uuid, current_setting(''zz.p0'')::date, null, ''ZZ Fractions'', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 5'', null)') = 'LPN01: You can only write plans for the classes and subjects you teach.')::text, 'true'),
    ('a plan must start on the first day of a period', (pg_temp.t_err(u_t1, 'select public.save_lesson_plan(null, current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date + 1, null, ''ZZ Fractions'', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 5'', null)') = 'LPN01: A plan starts on the first day of a plan period.')::text, 'true'),
    ('a plan needs a topic', (pg_temp.t_err(u_t1, 'select public.save_lesson_plan(null, current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date, null, '' '', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 5'', null)') = 'LPN01: Say what the topic is.')::text, 'true'),
    ('the teacher plans fractions for the period, from the syllabus', pg_temp.t_try(u_t1, 'select public.save_lesson_plan(null, current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date, (select id from public.syllabus_topics where title = ''ZZ Fractions''), ''ZZ Fractions'', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 5'', null)'), 'ok:1'),
    ('the plan is a draft', pg_temp.t_scalar('select status from public.lesson_plans where topic = ''ZZ Fractions'''), 'draft'),
    ('it remembers the syllabus topic', pg_temp.t_scalar('select (topic_id is not null)::text from public.lesson_plans where topic = ''ZZ Fractions'''), 'true'),
    ('a second plan for the same class and period is refused', (pg_temp.t_err(u_t1, 'select public.save_lesson_plan(null, current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date, null, ''ZZ Fractions'', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 5'', null)') = 'LPN01: There is already a plan for this class and subject for that period.')::text, 'true'),
    ('the teacher sees it', pg_temp.t_try(u_t1, 'select 1 from public.lesson_plans where topic like ''ZZ%'''), 'ok:1'),
    ('the admin sees it', pg_temp.t_try(u_admin, 'select 1 from public.lesson_plans where topic like ''ZZ%'''), 'ok:1'),
    ('the principal sees it', pg_temp.t_try(u_prin, 'select 1 from public.lesson_plans where topic like ''ZZ%'''), 'ok:1'),
    ('HR does not', pg_temp.t_try(u_hr, 'select 1 from public.lesson_plans where topic like ''ZZ%'''), 'ok:0'),
    ('reception does not', pg_temp.t_try(u_rec, 'select 1 from public.lesson_plans where topic like ''ZZ%'''), 'ok:0'),
    ('a parent does not', pg_temp.t_try(u_p1, 'select 1 from public.lesson_plans where topic like ''ZZ%'''), 'ok:0'),
    ('another school does not', pg_temp.t_try(u_adminb, 'select 1 from public.lesson_plans where topic like ''ZZ%'''), 'ok:0'),
    ('a teacher cannot write straight into the table', pg_temp.t_try(u_t1, format('insert into public.lesson_plans (class_subject_id,week_start,topic) values (current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date + 14, ''ZZ Direct'')')), 'denied'),
    ('or approve their own plan by editing it', pg_temp.t_try(u_t1, 'update public.lesson_plans set status = ''approved'' where topic = ''ZZ Fractions'''), 'ok:0'),
    ('a plan with no objectives cannot be submitted', (pg_temp.t_err(u_t1, 'select public.save_lesson_plan((select id from public.lesson_plans where topic = ''ZZ Fractions''), current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date, null, ''ZZ Fractions'', '''', null, null, null, null)') = 'ok')::text, 'true'),
    ('(the objectives are now empty)', (pg_temp.t_err(u_t1, 'select public.submit_lesson_plan((select id from public.lesson_plans where topic = ''ZZ Fractions''))') = 'LPN01: Add the objectives before submitting.')::text, 'true'),
    ('the teacher adds them', pg_temp.t_try(u_t1, 'select public.save_lesson_plan((select id from public.lesson_plans where topic = ''ZZ Fractions''), current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date, null, ''ZZ Fractions'', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 5'', null)'), 'ok:1'),
    ('only the author can submit it', (pg_temp.t_err(u_admin, 'select public.submit_lesson_plan((select id from public.lesson_plans where topic = ''ZZ Fractions''))') like 'LPN01: You can only submit your own plans.')::text, 'true'),
