    ('it is submitted', pg_temp.t_scalar('select status from public.lesson_plans where topic = ''ZZ Fractions'''), 'submitted'),
    ('the admin is told', pg_temp.t_try(u_admin, 'select 1 from public.notifications where title = ''Lesson plan to review'' and body like ''%ZLP%ZZ Fractions'''), 'ok:1'),
    ('so is the principal', pg_temp.t_try(u_prin, 'select 1 from public.notifications where title = ''Lesson plan to review'''), 'ok:1'),
    ('the teacher is not', pg_temp.t_try(u_t1, 'select 1 from public.notifications where title = ''Lesson plan to review'''), 'ok:0'),
    ('a submitted plan cannot be changed', (pg_temp.t_err(u_t1, 'select public.save_lesson_plan((select id from public.lesson_plans where topic = ''ZZ Fractions''), current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date, null, ''ZZ Fractions'', ''Changed'', null, null, null, null)') = 'LPN01: This plan has been submitted or approved and cannot be changed.')::text, 'true'),
