    ('the teacher can edit it again', pg_temp.t_try(u_t1, 'select public.save_lesson_plan((select id from public.lesson_plans where topic = ''ZZ Fractions''), current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date, null, ''ZZ Fractions'', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 6 questions 1 to 5'', null)'), 'ok:1'),
    ('and submit it again', pg_temp.t_try(u_t1, 'select public.submit_lesson_plan((select id from public.lesson_plans where topic = ''ZZ Fractions''))'), 'ok:1'),
    ('which clears the old comment', pg_temp.t_scalar('select (review_comment is null and reviewed_at is null)::text from public.lesson_plans where topic = ''ZZ Fractions'''), 'true'),
    ('the principal approves it', pg_temp.t_try(u_prin, 'select public.review_lesson_plan((select id from public.lesson_plans where topic = ''ZZ Fractions''), ''approved'', ''Good plan'')'), 'ok:1'),
    ('it is approved, by the principal', pg_temp.t_scalar('select status || '' '' || (select full_name from public.profiles where id = reviewed_by) from public.lesson_plans where topic = ''ZZ Fractions'''), 'approved principal'),
    ('the teacher is told', pg_temp.t_try(u_t1, 'select 1 from public.notifications where title = ''Lesson plan approved'''), 'ok:1'),
    ('an approved plan cannot be changed', (pg_temp.t_err(u_t1, 'select public.save_lesson_plan((select id from public.lesson_plans where topic = ''ZZ Fractions''), current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date, null, ''ZZ Fractions'', ''Changed'', null, null, null, null)') = 'LPN01: This plan has been submitted or approved and cannot be changed.')::text, 'true'),
    ('nor reviewed again', (pg_temp.t_err(u_admin, 'select public.review_lesson_plan((select id from public.lesson_plans where topic = ''ZZ Fractions''), ''changes_requested'', ''Too late'')') = 'LPN01: Only a submitted plan can be reviewed.')::text, 'true'),
    ('the teacher cannot remove a plan that is not a draft', pg_temp.t_try(u_t1, 'delete from public.lesson_plans where topic = ''ZZ Fractions'''), 'ok:0'),
    ('a draft for the next period can be removed by its author', pg_temp.t_try(u_t1, 'select public.save_lesson_plan(null, current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date + 7, null, ''ZZ Next week'', null, null, null, null, null)'), 'ok:1'),
    ('the draft is there', pg_temp.t_try(u_t1, 'select 1 from public.lesson_plans where topic = ''ZZ Next week'''), 'ok:1'),
    ('the teacher removes it', pg_temp.t_try(u_t1, 'delete from public.lesson_plans where topic = ''ZZ Next week'''), 'ok:1'),
    ('a teacher cannot open the tracker', (pg_temp.t_val(u_t1, 'select count(*)::text from public.lesson_plan_tracker(current_setting(''zz.p0'')::date)') like '42501%')::text, 'true'),
    ('the admin sees who has planned: this class is approved', pg_temp.t_val(u_admin, 'select status || '' '' || topic from public.lesson_plan_tracker(current_setting(''zz.p0'')::date) where class_subject_id = current_setting(''zz.lcs'')::uuid'), 'approved ZZ Fractions'),
    ('for the next period it has not been planned', pg_temp.t_val(u_admin, 'select coalesce(status, ''not started'') from public.lesson_plan_tracker(current_setting(''zz.p0'')::date + 7) where class_subject_id = current_setting(''zz.lcs'')::uuid'), 'not started'),
    ('the tracker names the teacher', pg_temp.t_val(u_admin, 'select teacher_name from public.lesson_plan_tracker(current_setting(''zz.p0'')::date) where class_subject_id = current_setting(''zz.lcs'')::uuid'), 'teacher1'),
    ('classes without a teacher are left out', pg_temp.t_val(u_admin, 'select count(*)::text from public.lesson_plan_tracker(current_setting(''zz.p0'')::date) where teacher_name is null'), '0'),
    ('the admin makes plans fortnightly, due on Monday, with no review', pg_temp.t_try(u_admin, 'select public.save_lesson_plan_settings(2, 1, false)'), 'ok:1'),
    ('the schedule follows', pg_temp.t_val(u_t1, 'select (public.lesson_plan_schedule()->>''periodWeeks'') || '' '' || (public.lesson_plan_schedule()->>''dueWeekday'') || '' '' || (public.lesson_plan_schedule()->>''requireReview'')'), '2 1 false'),
    ('a period is now two weeks', pg_temp.t_val(u_t1, 'select (((public.lesson_plan_schedule()->''current''->>''end'')::date - (public.lesson_plan_schedule()->''current''->>''start'')::date) = 13)::text'), 'true'),
    ('plans are due a week before the period begins when due on a Monday', pg_temp.t_val(u_t1, 'select (((public.lesson_plan_schedule()->''next''->>''start'')::date - (public.lesson_plan_schedule()->''next''->>''dueOn'')::date) = 7)::text'), 'true'),
    ('the fortnight starts on a Monday', pg_temp.t_scalar('select set_config(''zz.p2'', public._plan_period_start((select school_id from public.profiles where full_name = ''teacher1''), current_date)::text, true) is not null'), 'true'),
    ('(a Monday again)', pg_temp.t_scalar('select (extract(isodow from current_setting(''zz.p2'')::date) = 1)::text'), 'true'),
    ('a plan cannot start in the second week of a fortnight', (pg_temp.t_err(u_t1, 'select public.save_lesson_plan(null, current_setting(''zz.lcs'')::uuid, current_setting(''zz.p2'')::date + 7, null, ''ZZ Fortnight'', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 5'', null)') = 'LPN01: A plan starts on the first day of a plan period.')::text, 'true'),
    ('but can start at the beginning of one', pg_temp.t_try(u_t1, 'select public.save_lesson_plan(null, current_setting(''zz.lcs'')::uuid, current_setting(''zz.p2'')::date + 14, null, ''ZZ Fortnight'', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 5'', null)'), 'ok:1'),
    ('with review off nobody is asked to review it', pg_temp.t_try(u_t1, 'select public.submit_lesson_plan((select id from public.lesson_plans where topic = ''ZZ Fortnight''))'), 'ok:1'),
    ('so there is no new note to the admin', pg_temp.t_try(u_admin, 'select 1 from public.notifications where title = ''Lesson plan to review'' and body like ''%ZZ Fortnight'''), 'ok:0'),
    ('a sunday due day is the day before', pg_temp.t_try(u_admin, 'select public.save_lesson_plan_settings(1, 7, true)'), 'ok:1'),
    ('so plans are due 1 day before', pg_temp.t_val(u_t1, 'select (((public.lesson_plan_schedule()->''next''->>''start'')::date - (public.lesson_plan_schedule()->''next''->>''dueOn'')::date) = 1)::text'), 'true'),
    ('the admin puts the rules back', pg_temp.t_try(u_admin, 'select public.save_lesson_plan_settings(1, 5, true)'), 'ok:1'),
    ('the admin switches the module off', pg_temp.t_try(u_admin, 'select public.set_school_features((select array_agg(key) from public.app_features where key <> ''lessons''))'), 'ok:1'),
    ('the teacher sees no plans', pg_temp.t_try(u_t1, 'select 1 from public.lesson_plans'), 'ok:0'),
    ('nor the syllabus', pg_temp.t_try(u_t1, 'select 1 from public.syllabus_topics'), 'ok:0'),
    ('and cannot write one', (pg_temp.t_err(u_t1, 'select public.save_lesson_plan(null, current_setting(''zz.lcs'')::uuid, current_setting(''zz.p0'')::date, null, ''ZZ Off'', ''Add and subtract fractions'', ''Group work'', ''Counters'', ''Page 5'', null)') like '42501%')::text, 'true'),
    ('the admin switches everything back on', pg_temp.t_try(u_admin, format('select public.set_school_features(%s)', '(select array_agg(key) from public.app_features)')), 'ok:1'),
    ('a teacher can write plans and see the syllabus but not review', pg_temp.t_try(u_t1, 'select 1 where public.has_capability(''lessons.write_own'') and public.has_capability(''lessons.view_syllabus'') and not public.has_capability(''lessons.review'') and not public.has_capability(''lessons.manage_syllabus'')'), 'ok:1'),
    ('the admin can review and manage the syllabus', pg_temp.t_try(u_admin, 'select 1 where public.has_capability(''lessons.review'') and public.has_capability(''lessons.manage_syllabus'')'), 'ok:1'),
    ('the admin can download', pg_temp.t_try(u_admin, 'select 1 where public.has_capability(''lessons.download'')'), 'ok:1'),
    ('a teacher cannot', pg_temp.t_try(u_t1, 'select 1 where public.has_capability(''lessons.download'')'), 'ok:0'),
    ('a developer holds every action', pg_temp.t_try(u_dev, 'select 1 where public.has_capability(''lessons.write_own'') and public.has_capability(''lessons.review'') and public.has_capability(''lessons.manage_syllabus'')'), 'ok:1'),
    -- Staff clock-in
    ('a teacher reads the defaults: staff clock in by code', pg_temp.t_val(u_t1, 'select public.clockin_config()->>''mode'''), 'self'),
    ('the day starts at half past seven', pg_temp.t_val(u_t1, 'select public.clockin_config()->>''workStart'''), '07:30'),
    ('with 15 minutes'' grace', pg_temp.t_val(u_t1, 'select public.clockin_config()->>''graceMinutes'''), '15'),
    ('a parent cannot ask', (pg_temp.t_val(u_p1, 'select public.clockin_config()::text') like '42501%')::text, 'true'),
    ('a teacher cannot change the setup', (pg_temp.t_val(u_t1, 'select public.save_clockin_settings(''both'', ''07:00''::time, 10, ''15:00''::time)') like '42501%')::text, 'true'),
    ('nor start a new secret', (pg_temp.t_val(u_t1, 'select public.rotate_clockin_secret()::text') like '42501%')::text, 'true'),
    ('a mode must be one of the three', (pg_temp.t_err(u_admin, 'select public.save_clockin_settings(''sometimes'', ''07:00''::time, 10, ''15:00''::time)') = 'CLK01: Choose how staff clock in.')::text, 'true'),
    ('the grace period is at most 120 minutes', (pg_temp.t_err(u_admin, 'select public.save_clockin_settings(''self'', ''07:00''::time, 121, ''15:00''::time)') = 'CLK01: The grace period is 0 to 120 minutes.')::text, 'true'),
    ('the day must end after it starts', (pg_temp.t_err(u_admin, 'select public.save_clockin_settings(''self'', ''15:00''::time, 10, ''07:00''::time)') = 'CLK01: The day must end after it starts.')::text, 'true'),
    ('the admin sets a day that cannot be late', pg_temp.t_try(u_admin, 'select public.save_clockin_settings(''self'', ''23:59''::time, 0, ''23:59:59''::time)'), 'ok:1'),
    ('the settings, which hold the secret, cannot be read by the admin', pg_temp.t_try(u_admin, 'select 1 from public.clockin_settings'), 'ok:0'),
    ('nor by a developer', pg_temp.t_try(u_dev, 'select 1 from public.clockin_settings'), 'ok:0'),
    ('the helper that makes codes cannot be called by a teacher', (pg_temp.t_val(u_t1, 'select public._clockin_code(''x'', 1)') like '42501%')::text, 'true'),
    ('reception can show the code, which is six digits', (pg_temp.t_val(u_rec, 'select public.clockin_current_code()->>''code''') ~ '^[0-9]{6}$')::text, 'true'),
    ('the code on the screen is noted', (set_config('zz.shown', pg_temp.t_val(u_rec, 'select public.clockin_current_code()->>''code'''), true) ~ '^[0-9]{6}$')::text, 'true'),
    ('the code is the one made from the secret and this half minute', pg_temp.t_scalar('select ((public._clockin_code((select secret from public.clockin_settings where school_id = (select school_id from public.profiles where full_name = ''teacher1'')), floor(extract(epoch from now()) / 30)::bigint)) = current_setting(''zz.shown''))::text'), 'true'),
    ('it says how long it has left, up to 30 seconds', ((pg_temp.t_val(u_rec, 'select public.clockin_current_code()->>''expiresIn'''))::int between 1 and 30)::text, 'true'),
    ('a teacher cannot show it', (pg_temp.t_val(u_t1, 'select public.clockin_current_code()::text') like '42501%')::text, 'true'),
    ('a parent cannot', (pg_temp.t_val(u_p1, 'select public.clockin_current_code()::text') like '42501%')::text, 'true'),
    ('the code for this half minute is ready', pg_temp.t_scalar('select (set_config(''zz.code'', public._clockin_code((select secret from public.clockin_settings where school_id = (select school_id from public.profiles where full_name = ''teacher1'')), floor(extract(epoch from now()) / 30)::bigint), true) is not null)::text'), 'true'),
    ('a teacher clocks in and is told it worked', pg_temp.t_val(u_t1, 'select (public.clock_in(current_setting(''zz.code''), null, ''dev-aaaa-1111'', ''a phone'', null))->>''ok'''), 'true'),
    ('the first clock-in of the day is an ''in''', pg_temp.t_scalar(format('select kind from public.clockin_events where profile_id = %L order by captured_at limit 1', u_t1)), 'in'),
    ('and not flagged, the phone being the first they have used', pg_temp.t_scalar(format('select cardinality(flags)::text from public.clockin_events where profile_id = %L order by captured_at limit 1', u_t1)), '0'),
    ('that phone is registered and approved', pg_temp.t_scalar(format('select approved::text from public.clockin_devices where profile_id = %L', u_t1)), 'true'),
    ('a second scan at once is not recorded again', pg_temp.t_val(u_t1, 'select (public.clock_in(current_setting(''zz.code''), null, ''dev-aaaa-1111'', ''a phone'', null))->>''duplicate'''), 'true'),
    ('so there is still one entry', pg_temp.t_scalar(format('select count(*)::text from public.clockin_events where profile_id = %L', u_t1)), '1'),
    ('the time is the school''s day', pg_temp.t_scalar(format('select (day = public._clockin_today())::text from public.clockin_events where profile_id = %L limit 1', u_t1)), 'true'),
    ('a wrong code is an answer, not an error', pg_temp.t_val(u_t1, 'select (public.clock_in(''00000x'', null, ''dev-aaaa-1111'', ''a phone'', null))->>''ok'''), 'false'),
    ('a parent cannot clock in', (pg_temp.t_val(u_p1, 'select (public.clock_in(current_setting(''zz.code''), null, ''dev-aaaa-1111'', ''a phone'', null))->>''ok''') like '42501%')::text, 'true'),
    ('a deactivated account cannot', (pg_temp.t_val(u_off, 'select (public.clock_in(current_setting(''zz.code''), null, ''dev-aaaa-1111'', ''a phone'', null))->>''ok''') like '42501%')::text, 'true'),
    ('a phone must be identifiable', (pg_temp.t_err(u_t1, 'select public.clock_in(current_setting(''zz.code''), null, ''x'', ''a phone'', null)') = 'CLK01: This phone could not be identified.')::text, 'true'),
    ('a kind must be in or out', (pg_temp.t_err(u_t1, 'select public.clock_in(current_setting(''zz.code''), ''lunch'', ''dev-aaaa-1111'', ''a phone'', null)') = 'CLK01: Choose in or out.')::text, 'true'),
    ('the same teacher uses another phone to clock out', pg_temp.t_val(u_t1, 'select (public.clock_in(current_setting(''zz.code''), ''out'', ''dev-bbbb-2222'', ''a phone'', null))->>''ok'''), 'true'),
    ('it was recorded', pg_temp.t_scalar(format('select count(*)::text from public.clockin_events where profile_id = %L', u_t1)), '2'),
    ('and flagged as a new phone', pg_temp.t_scalar(format('select (''new_device'' = any (flags))::text from public.clockin_events where profile_id = %L and kind = ''out''', u_t1)), 'true'),
    ('the new phone waits for approval', pg_temp.t_scalar(format('select approved::text from public.clockin_devices where profile_id = %L and device_hash <> (select device_hash from public.clockin_devices where profile_id = %L and approved)', u_t1, u_t1)), 'false'),
    ('the head sees the teacher''s phones', (pg_temp.t_val(u_admin, format('select count(*)::text from public.clockin_devices_list() where profile_id = %L', u_t1)) = '2')::text, 'true'),
    ('the head approves the new phone', pg_temp.t_try(u_admin, format('select public.set_clockin_device_approved((select id from public.clockin_devices where profile_id = %L and not approved), true)', u_t1)), 'ok:1'),
    ('a teacher cannot approve phones', (pg_temp.t_val(u_t1, 'select public.set_clockin_device_approved(gen_random_uuid(), true)::text') like '42501%')::text, 'true'),
    ('a teacher sees only their own phones', (pg_temp.t_val(u_t1, format('select count(*)::text from public.clockin_devices_list() where profile_id <> %L', u_t1)) = '0')::text, 'true'),
    ('a scan from a phone that was offline five minutes ago is accepted', pg_temp.t_scalar('select (set_config(''zz.code'', public._clockin_code((select secret from public.clockin_settings where school_id = (select school_id from public.profiles where full_name = ''teacher1'')), floor(extract(epoch from now() - interval ''300 seconds'') / 30)::bigint), true) is not null)::text'), 'true'),
    ('HR''s offline scan counts', pg_temp.t_val(u_hr, 'select (public.clock_in(current_setting(''zz.code''), null, ''dev-hhhh-3333'', ''a phone'', now() - interval ''5 minutes''))->>''ok'''), 'true'),
    ('and is flagged as offline', pg_temp.t_scalar(format('select (''offline'' = any (flags))::text from public.clockin_events where profile_id = %L', u_hr)), 'true'),
    ('the entry carries the time it was scanned, not when it arrived', pg_temp.t_scalar(format('select (received_at - captured_at > interval ''4 minutes'')::text from public.clockin_events where profile_id = %L', u_hr)), 'true'),
    ('a scan three days old is not accepted', pg_temp.t_val(u_hr, 'select (public.clock_in(''123456'', null, ''dev-hhhh-3333'', ''a phone'', now() - interval ''3 days''))->>''ok'''), 'false'),
    ('nor one from ten minutes in the future', pg_temp.t_val(u_hr, 'select (public.clock_in(''123456'', null, ''dev-hhhh-3333'', ''a phone'', now() + interval ''10 minutes''))->>''ok'''), 'false'),
    ('the current code is ready again', pg_temp.t_scalar('select (set_config(''zz.code'', public._clockin_code((select secret from public.clockin_settings where school_id = (select school_id from public.profiles where full_name = ''teacher1'')), floor(extract(epoch from now()) / 30)::bigint), true) is not null)::text'), 'true'),
    ('a second ''in'' straight after an ''in'' is flagged as a repeat', pg_temp.t_val(u_hr, 'select (public.clock_in(current_setting(''zz.code''), ''in'', ''dev-hhhh-3333'', ''a phone'', null))->''flags''::text'), '["repeat"]'),
    ('someone''s first scan of the day being ''out'' is flagged', pg_temp.t_val(u_prin, 'select (public.clock_in(current_setting(''zz.code''), ''out'', ''dev-pppp-4444'', ''a phone'', null))->''flags''::text'), '["out_without_in"]'),
    ('the head makes any time after midnight late', pg_temp.t_try(u_admin, 'select public.save_clockin_settings(''self'', ''00:00''::time, 0, ''23:59''::time)'), 'ok:1'),
    ('reception clocks in', pg_temp.t_val(u_rec, 'select (public.clock_in(current_setting(''zz.code''), ''in'', ''dev-rrrr-5555'', ''a phone'', null))->''flags''::text'), '["late"]'),
    ('a second ''in'' by the same person is not late again', pg_temp.t_val(u_rec, 'select (public.clock_in(current_setting(''zz.code''), ''in'', ''dev-rrrr-5555'', ''a phone'', null))->''flags''::text'), '["repeat"]'),
    ('a day with grace is not late', pg_temp.t_try(u_admin, 'select public.save_clockin_settings(''self'', ''23:59''::time, 0, ''23:59:59''::time)'), 'ok:1'),
    ('HR sees the register', pg_temp.t_try(u_hr, 'select 1 where (select count(*) from public.clockin_roster(public._clockin_today(), public._clockin_today())) >= 0'), 'ok:1'),
    ('a teacher cannot', (pg_temp.t_val(u_t1, 'select public.clockin_roster(public._clockin_today(), public._clockin_today())::text') like '42501%')::text, 'true'),
    ('a parent cannot', (pg_temp.t_val(u_p1, 'select public.clockin_roster(public._clockin_today(), public._clockin_today())::text') like '42501%')::text, 'true'),
    ('the teacher is present', (case when extract(isodow from public._clockin_today()) > 5 then 'present' else pg_temp.t_val(u_admin, format('select status from public.clockin_roster(public._clockin_today(), public._clockin_today()) where profile_id = %L', u_t1)) end), 'present'),
    ('reception is late', (case when extract(isodow from public._clockin_today()) > 5 then 'late' else pg_temp.t_val(u_admin, format('select status from public.clockin_roster(public._clockin_today(), public._clockin_today()) where profile_id = %L', u_rec)) end), 'late'),
    ('the accountant, who did not clock in, is absent', (case when extract(isodow from public._clockin_today()) > 5 then 'absent' else pg_temp.t_val(u_admin, format('select status from public.clockin_roster(public._clockin_today(), public._clockin_today()) where profile_id = %L', u_acc)) end), 'absent'),
    ('a deactivated account is not on the register', (pg_temp.t_val(u_admin, format('select count(*)::text from public.clockin_roster(public._clockin_today(), public._clockin_today()) where profile_id = %L', u_off)) = '0')::text, 'true'),
    ('a run longer than 92 days is refused', (pg_temp.t_err(u_admin, 'select public.clockin_roster(public._clockin_today() - 100, public._clockin_today())') = 'CLK01: Choose up to 92 days.')::text, 'true'),
    ('a weekend is not counted', (pg_temp.t_val(u_admin, 'select count(*)::text from public.clockin_roster(''2026-10-31'', ''2026-11-01'')') = '0')::text, 'true'),
    ('a teacher reads their own entries', pg_temp.t_try(u_t1, 'select 1 where exists (select 1 from public.clockin_events where profile_id = auth.uid())'), 'ok:1'),
    ('but no one else''s', pg_temp.t_try(u_t1, 'select 1 from public.clockin_events where profile_id <> auth.uid()'), 'ok:0'),
    ('HR reads everyone''s', pg_temp.t_try(u_hr, 'select 1 where exists (select 1 from public.clockin_events where profile_id <> auth.uid())'), 'ok:1'),
    ('a parent reads none', pg_temp.t_try(u_p1, 'select 1 from public.clockin_events'), 'ok:0'),
    ('another school reads none', pg_temp.t_try(u_adminb, 'select 1 from public.clockin_events'), 'ok:0'),
    ('a teacher cannot write an entry directly', pg_temp.t_try(u_t1, 'insert into public.clockin_events (profile_id, kind, day, captured_at) values (auth.uid(), ''in'', current_date, now())'), 'denied'),
    ('nor change one', pg_temp.t_try(u_t1, 'update public.clockin_events set kind = ''out'' where profile_id = auth.uid()'), 'ok:0'),
    ('nor delete one', pg_temp.t_try(u_t1, 'delete from public.clockin_events where profile_id = auth.uid()'), 'ok:0'),
    ('my own entries come back newest first', (pg_temp.t_val(u_t1, 'select count(*)::text from public.my_clockin_events(14)') = '2')::text, 'true'),
    ('the accountant is not yet chosen', pg_temp.t_val(u_acc, 'select public.is_clockin_taker()::text'), 'false'),
    ('a teacher cannot choose someone', (pg_temp.t_val(u_t1, 'select public.save_clockin_taker((select id from public.profiles limit 1), null, null)::text') like '42501%')::text, 'true'),
    ('the head chooses the accountant, with no dates', pg_temp.t_try(u_admin, format('select public.save_clockin_taker(%L, null, null)', u_acc)), 'ok:1'),
    ('they are now the one who takes attendance', pg_temp.t_val(u_acc, 'select public.is_clockin_taker()::text'), 'true'),
    ('but while staff clock in by code alone, that does not open the register to them', (pg_temp.t_val(u_acc, 'select public.clockin_roster(public._clockin_today(), public._clockin_today())::text') like '42501%')::text, 'true'),
    ('nor let them mark anyone', (pg_temp.t_val(u_acc, 'select public.mark_staff_clock((select id from public.profiles where full_name = ''teacher1''), public._clockin_today(), ''in'', ''08:00'', null)::text') like '42501%')::text, 'true'),
    ('the head lets staff use both ways', pg_temp.t_try(u_admin, 'select public.save_clockin_settings(''both'', ''07:30''::time, 15, ''15:30''::time)'), 'ok:1'),
    ('now the accountant sees the register', pg_temp.t_try(u_acc, 'select 1 where (select count(*) from public.clockin_roster(public._clockin_today(), public._clockin_today())) >= 0'), 'ok:1'),
    ('and marks the teacher in at nine, which is late', pg_temp.t_try(u_acc, format('select public.mark_staff_clock(%L, public._clockin_today() - 1, ''in'', ''09:00'', ''came with a note'')', u_t1)), 'ok:1'),
    ('the entry says it was marked by hand, by the accountant', pg_temp.t_scalar(format('select (source = ''marked'' and marked_by = %L and ''late'' = any (flags) and note = ''came with a note'')::text from public.clockin_events where profile_id = %L and source = ''marked''', u_acc, u_t1)), 'true'),
    ('a teacher who is not chosen cannot mark', (pg_temp.t_val(u_t1, format('select public.mark_staff_clock(%L, public._clockin_today(), ''in'', ''08:00'', null)::text', u_rec)) like '42501%')::text, 'true'),
    ('a day that has not come cannot be marked', (pg_temp.t_err(u_acc, format('select public.mark_staff_clock(%L, public._clockin_today() + 1, ''in'', ''08:00'', null)', u_t1)) = 'CLK01: You cannot mark a day that has not come.')::text, 'true'),
    ('a chosen person cannot go back more than 14 days', (pg_temp.t_err(u_acc, format('select public.mark_staff_clock(%L, public._clockin_today() - 20, ''in'', ''08:00'', null)', u_t1)) = 'CLK01: You can mark up to 14 days back. Ask the head for older days.')::text, 'true'),
    ('the head can', pg_temp.t_try(u_admin, format('select public.mark_staff_clock(%L, public._clockin_today() - 20, ''in'', ''08:00'', null)', u_t1)), 'ok:1'),
    ('a parent is not staff to be marked', (pg_temp.t_err(u_acc, format('select public.mark_staff_clock(%L, public._clockin_today(), ''in'', ''08:00'', null)', u_p1)) = 'CLK01: Choose a member of staff.')::text, 'true'),
    ('the marked entry''s id is noted', pg_temp.t_scalar(format('select (set_config(''zz.mk'', (select id::text from public.clockin_events where profile_id = %L and source = ''marked'' and marked_by = %L and day = public._clockin_today() - 1), true) is not null)::text', u_t1, u_acc)), 'true'),
    ('the accountant removes their own mistaken entry', pg_temp.t_try(u_acc, 'select public.remove_marked_clock(current_setting(''zz.mk'')::uuid)'), 'ok:1'),
    ('a scanned entry cannot be removed, even by the head', (pg_temp.t_err(u_admin, format('select public.remove_marked_clock((select id from public.clockin_events where profile_id = %L and source = ''code'' limit 1))', u_t1)) = 'CLK01: Only an entry marked by hand can be removed.')::text, 'true'),
    ('the accountant''s turn ends yesterday', pg_temp.t_try(u_admin, format('select public.save_clockin_taker(%L, null, public._clockin_today() - 1)', u_acc)), 'ok:1'),
    ('so they are no longer the one', pg_temp.t_val(u_acc, 'select public.is_clockin_taker()::text'), 'false'),
    ('and cannot mark', (pg_temp.t_val(u_acc, 'select public.mark_staff_clock((select id from public.profiles where full_name = ''teacher1''), public._clockin_today(), ''in'', ''08:00'', null)::text') like '42501%')::text, 'true'),
    ('a turn that starts tomorrow does not count yet', pg_temp.t_try(u_admin, format('select public.save_clockin_taker(%L, public._clockin_today() + 1, null)', u_acc)), 'ok:1'),
    ('so they are not the one yet', pg_temp.t_val(u_acc, 'select public.is_clockin_taker()::text'), 'false'),
    ('the last day cannot come before the first', (pg_temp.t_err(u_admin, format('select public.save_clockin_taker(%L, public._clockin_today() + 2, public._clockin_today())', u_acc)) = 'CLK01: The last day cannot be before the first.')::text, 'true'),
    ('the head sees who takes attendance', (pg_temp.t_val(u_admin, 'select count(*)::text from public.list_clockin_takers()') = '1')::text, 'true'),
    ('the accountant sees only themselves', (pg_temp.t_val(u_acc, 'select count(*)::text from public.list_clockin_takers()') = '1')::text, 'true'),
    ('a teacher sees none', (pg_temp.t_val(u_t1, 'select count(*)::text from public.list_clockin_takers()') = '0')::text, 'true'),
    ('the head takes the accountant off', pg_temp.t_try(u_admin, 'select public.remove_clockin_taker((select id from public.clockin_takers limit 1))'), 'ok:1'),
    ('the head sets attendance to by hand only', pg_temp.t_try(u_admin, 'select public.save_clockin_settings(''taker'', ''07:30''::time, 15, ''15:30''::time)'), 'ok:1'),
    ('then clocking in by code is closed', (pg_temp.t_err(u_t1, 'select public.clock_in(''123456'', null, ''dev-aaaa-1111'', ''a phone'', null)') = 'CLK01: Staff do not clock in by code here. Ask the person taking attendance.')::text, 'true'),
    ('and the screen has no code to show', (pg_temp.t_err(u_rec, 'select public.clockin_current_code()') = 'CLK01: Clock-in by code is switched off. Staff are marked by hand.')::text, 'true'),
    ('back to by code', pg_temp.t_try(u_admin, 'select public.save_clockin_settings(''self'', ''23:59''::time, 0, ''23:59:59''::time)'), 'ok:1'),
    ('the code now', pg_temp.t_scalar('select (set_config(''zz.code'', public._clockin_code((select secret from public.clockin_settings where school_id = (select school_id from public.profiles where full_name = ''teacher1'')), floor(extract(epoch from now()) / 30)::bigint), true) is not null)::text'), 'true'),
    ('the head starts a new secret', pg_temp.t_try(u_admin, 'select public.rotate_clockin_secret()'), 'ok:1'),
    ('the code that was showing no longer works', pg_temp.t_val(u_hr, 'select (public.clock_in(current_setting(''zz.code''), ''out'', ''dev-hhhh-3333'', ''a phone'', null))->>''ok'''), 'false'),
    ('the new code does', pg_temp.t_scalar('select (set_config(''zz.code'', public._clockin_code((select secret from public.clockin_settings where school_id = (select school_id from public.profiles where full_name = ''teacher1'')), floor(extract(epoch from now()) / 30)::bigint), true) is not null)::text'), 'true'),
    ('and works', pg_temp.t_val(u_hr, 'select (public.clock_in(current_setting(''zz.code''), ''out'', ''dev-hhhh-3333'', ''a phone'', null))->>''ok'''), 'true'),
    ('eight wrong guesses', pg_temp.t_scalar('select ''8'''), '8'),
    ('are counted', (pg_temp.t_val(u_acc, 'select (public.clock_in(''000001'', null, ''dev-aaaa-9999'', ''a phone'', null))->>''ok''') = 'false' and pg_temp.t_val(u_acc, 'select (public.clock_in(''000002'', null, ''dev-aaaa-9999'', ''a phone'', null))->>''ok''') = 'false' and pg_temp.t_val(u_acc, 'select (public.clock_in(''000003'', null, ''dev-aaaa-9999'', ''a phone'', null))->>''ok''') = 'false' and pg_temp.t_val(u_acc, 'select (public.clock_in(''000004'', null, ''dev-aaaa-9999'', ''a phone'', null))->>''ok''') = 'false' and pg_temp.t_val(u_acc, 'select (public.clock_in(''000005'', null, ''dev-aaaa-9999'', ''a phone'', null))->>''ok''') = 'false' and pg_temp.t_val(u_acc, 'select (public.clock_in(''000006'', null, ''dev-aaaa-9999'', ''a phone'', null))->>''ok''') = 'false' and pg_temp.t_val(u_acc, 'select (public.clock_in(''000007'', null, ''dev-aaaa-9999'', ''a phone'', null))->>''ok''') = 'false' and pg_temp.t_val(u_acc, 'select (public.clock_in(''000008'', null, ''dev-aaaa-9999'', ''a phone'', null))->>''ok''') = 'false')::text, 'true'),
    ('after that even the right code is refused for a while', pg_temp.t_scalar('select (set_config(''zz.code'', public._clockin_code((select secret from public.clockin_settings where school_id = (select school_id from public.profiles where full_name = ''teacher1'')), floor(extract(epoch from now()) / 30)::bigint), true) is not null)::text'), 'true'),
    ('with a message saying to wait', (pg_temp.t_val(u_acc, 'select (public.clock_in(current_setting(''zz.code''), null, ''dev-aaaa-9999'', ''a phone'', null))->>''error''') like 'Too many wrong codes%')::text, 'true'),
    ('the head switches clock-in off', pg_temp.t_try(u_admin, 'select public.set_school_features((select array_agg(key) from public.app_features where key <> ''clockin''))'), 'ok:1'),
    ('then a teacher cannot clock in', (pg_temp.t_val(u_t1, 'select (public.clock_in(current_setting(''zz.code''), null, ''dev-aaaa-1111'', ''a phone'', null))->>''ok''') like '42501%')::text, 'true'),
    ('nor see the screen''s code', (pg_temp.t_val(u_rec, 'select public.clockin_current_code()::text') like '42501%')::text, 'true'),
    ('nor read their entries', pg_temp.t_try(u_t1, 'select 1 from public.clockin_events'), 'ok:0'),
    ('the head switches everything back on', pg_temp.t_try(u_admin, 'select public.set_school_features((select array_agg(key) from public.app_features))'), 'ok:1'),
    ('a teacher can clock in but not see everyone or set it up', pg_temp.t_try(u_t1, 'select 1 where public.has_capability(''clockin.use'') and not public.has_capability(''clockin.view_all'') and not public.has_capability(''clockin.manage'') and not public.has_capability(''clockin.display'')'), 'ok:1'),
    ('reception can show the screen', pg_temp.t_try(u_rec, 'select 1 where public.has_capability(''clockin.display'')'), 'ok:1'),
    ('HR sees and downloads', pg_temp.t_try(u_hr, 'select 1 where public.has_capability(''clockin.view_all'') and public.has_capability(''clockin.download'') and not public.has_capability(''clockin.manage'')'), 'ok:1'),
    ('the head holds every action, so can still give any role', pg_temp.t_try(u_admin, 'select 1 where public.has_capability(''clockin.use'') and public.has_capability(''clockin.display'') and public.has_capability(''clockin.view_all'') and public.has_capability(''clockin.manage'') and public.has_capability(''clockin.download'')'), 'ok:1'),
    ('the principal too', pg_temp.t_try(u_prin, 'select 1 where public.has_capability(''clockin.use'') and public.has_capability(''clockin.display'') and public.has_capability(''clockin.view_all'') and public.has_capability(''clockin.manage'') and public.has_capability(''clockin.download'')'), 'ok:1'),
    ('a developer holds every action', pg_temp.t_try(u_dev, 'select 1 where public.has_capability(''clockin.manage'') and public.has_capability(''clockin.display'')'), 'ok:1'),
    ('the head can list the staff to mark or to choose', pg_temp.t_try(u_admin, 'select 1 where (select count(*) from public.clockin_staff()) > 0'), 'ok:1'),
    ('a teacher cannot', (pg_temp.t_val(u_t1, 'select count(*)::text from public.clockin_staff()') like '42501%')::text, 'true'),
    ('a parent cannot', (pg_temp.t_val(u_p1, 'select count(*)::text from public.clockin_staff()') like '42501%')::text, 'true'),
    ('HR can see one person''s entries for a day', pg_temp.t_try(u_hr, format('select 1 where (select count(*) from public.clockin_day_entries(%L, public._clockin_today())) >= 0', u_t1)), 'ok:1'),
    ('a teacher cannot see someone''s day', (pg_temp.t_val(u_t1, format('select count(*)::text from public.clockin_day_entries(%L, public._clockin_today())', u_rec)) like '42501%')::text, 'true'),
    ('a parent cannot', (pg_temp.t_val(u_p1, format('select count(*)::text from public.clockin_day_entries(%L, public._clockin_today())', u_t1)) like '42501%')::text, 'true'),
    -- Complaints
    ('a parent raises an anonymous complaint', (set_config('zz.c1', pg_temp.t_val(u_p1, 'select public.submit_complaint(''fees'', ''ZZ Fee query'', ''I was charged twice for the same term.'', true)->>''id'''), true) is not null)::text, 'true'),
    ('another parent raises one openly, under their own name', (set_config('zz.c2', pg_temp.t_val(u_p2, 'select public.submit_complaint(''general'', ''ZZ Gate is unsafe'', ''The side gate is left open during break time.'', false)->>''id'''), true) is not null)::text, 'true'),
    ('a parent raises a safeguarding complaint, anonymously', (set_config('zz.c3', pg_temp.t_val(u_p1, 'select public.submit_complaint(''safeguarding'', ''ZZ Child at risk'', ''I am worried about something I saw at pickup.'', true)->>''id'''), true) is not null)::text, 'true'),
    ('the reference is random characters, not a running count', pg_temp.t_scalar('select (ref ~ ''^C[0-9]{2}-[0-9A-F]{5}$'')::text from public.complaints where id = current_setting(''zz.c1'')::uuid'), 'true'),
    ('a teacher can raise one', (pg_temp.t_val(u_t1, 'select public.submit_complaint(''staff_conduct'', ''ZZ Teacher raises'', ''A colleague keeps arriving very late to duty.'', true)->>''id''') is not null)::text, 'true'),
    ('HR can', (pg_temp.t_val(u_hr, 'select public.submit_complaint(''other'', ''ZZ HR raises'', ''A matter I would rather raise in writing here.'', false)->>''id''') is not null)::text, 'true'),
    ('a pupil can', (pg_temp.t_val(u_s1, 'select public.submit_complaint(''bullying'', ''ZZ Pupil raises'', ''Some older boys take my snack every day.'', true)->>''id''') is not null)::text, 'true'),
    ('a deactivated account cannot', (pg_temp.t_val(u_off, 'select public.submit_complaint(''general'', ''ZZ Nope'', ''I should not be able to send this one.'', false)->>''id''') like '42501%')::text, 'true'),
    ('a category must be one of the list', (pg_temp.t_err(u_p1, 'select public.submit_complaint(''weather'', ''ZZ Bad'', ''This has a bad category name.'', false)') = 'CMP01: Choose what the complaint is about.')::text, 'true'),
    ('a title needs three characters', (pg_temp.t_err(u_p1, 'select public.submit_complaint(''general'', ''ab'', ''This has a title that is too short.'', false)') = 'CMP01: Give the complaint a short title (3 to 120 characters).')::text, 'true'),
    ('a body needs a sentence', (pg_temp.t_err(u_p1, 'select public.submit_complaint(''general'', ''ZZ Short'', ''tiny'', false)') = 'CMP01: Say what happened, in at least a sentence (up to 4000 characters).')::text, 'true'),
    ('the pupil raises another (2)', (pg_temp.t_val(u_s1, 'select public.submit_complaint(''general'', ''ZZ Pupil 2'', ''Another thing that is worth looking at, number 2.'', true)->>''id''') is not null)::text, 'true'),
    ('the pupil raises another (3)', (pg_temp.t_val(u_s1, 'select public.submit_complaint(''general'', ''ZZ Pupil 3'', ''Another thing that is worth looking at, number 3.'', true)->>''id''') is not null)::text, 'true'),
    ('the pupil raises another (4)', (pg_temp.t_val(u_s1, 'select public.submit_complaint(''general'', ''ZZ Pupil 4'', ''Another thing that is worth looking at, number 4.'', true)->>''id''') is not null)::text, 'true'),
    ('the pupil raises another (5)', (pg_temp.t_val(u_s1, 'select public.submit_complaint(''general'', ''ZZ Pupil 5'', ''Another thing that is worth looking at, number 5.'', true)->>''id''') is not null)::text, 'true'),
    ('a sixth in a day is refused', (pg_temp.t_err(u_s1, 'select public.submit_complaint(''general'', ''ZZ Pupil six'', ''One more thing that is worth looking at.'', true)') = 'CMP01: You have sent several complaints today. Please wait until tomorrow, or speak to the school office.')::text, 'true'),
    ('the admin cannot read complaints directly', pg_temp.t_try(u_admin, 'select 1 from public.complaints'), 'denied'),
    ('the admin cannot read complaint_submitters directly', pg_temp.t_try(u_admin, 'select 1 from public.complaint_submitters'), 'denied'),
