    ('nor change a complaint directly', pg_temp.t_try(u_p1, 'update public.complaints set status = ''closed'''), 'denied'),
    ('no trigger copies who made a change into the audit log', pg_temp.t_scalar('select count(*)::text from pg_trigger t where not t.tgisinternal and t.tgrelid in (''public.complaints''::regclass, ''public.complaint_submitters''::regclass, ''public.complaint_messages''::regclass)'), '0'),
    ('the admin sees the complaints', ((pg_temp.t_val(u_admin, 'select count(*)::text from public.complaints_list() where subject like ''ZZ%'''))::int >= 3)::text, 'true'),
    ('the anonymous one has no name', pg_temp.t_val(u_admin, 'select coalesce(submitter_name, ''none'') from public.complaints_list() where subject = ''ZZ Fee query'''), 'none'),
