    ('the open one carries the name', pg_temp.t_val(u_admin, 'select submitter_name from public.complaints_list() where subject = ''ZZ Gate is unsafe'''), 'parent2'),
    ('the principal sees the anonymous one with no name too', pg_temp.t_val(u_prin, 'select coalesce(submitter_name, ''none'') from public.complaints_list() where subject = ''ZZ Fee query'''), 'none'),
    ('a developer sees it, still with no name', pg_temp.t_val(u_dev, 'select coalesce(submitter_name, ''none'') from public.complaints_list() where subject = ''ZZ Fee query'''), 'none'),
    ('a teacher sees none', pg_temp.t_val(u_t1, 'select count(*)::text from public.complaints_list() where subject like ''ZZ%'''), '0'),
    ('a parent sees none', pg_temp.t_val(u_p1, 'select count(*)::text from public.complaints_list() where subject like ''ZZ%'''), '0'),
    ('HR, who does not handle complaints, sees none', pg_temp.t_val(u_hr, 'select count(*)::text from public.complaints_list() where subject like ''ZZ%'''), '0'),
    ('another school sees none', pg_temp.t_val(u_adminb, 'select count(*)::text from public.complaints_list() where subject like ''ZZ%'''), '0'),
    ('the admin was told when complaints arrived', pg_temp.t_scalar(format('select (count(*) >= 3)::text from public.notifications where profile_id = %L and title = ''New complaint''', u_admin)), 'true'),
    ('and of the safeguarding one in its own words', pg_temp.t_scalar(format('select (count(*) >= 1)::text from public.notifications where profile_id = %L and title = ''New safeguarding complaint''', u_admin)), 'true'),
    ('none of those messages says who it is from', pg_temp.t_scalar(format('select count(*)::text from public.notifications where profile_id = %L and title like ''New%%complaint'' and (body ilike ''%%parent%%'' or title ilike ''%%parent%%'')', u_admin)), '0'),
    ('the admin sees the safeguarding complaint', pg_temp.t_val(u_admin, 'select count(*)::text from public.complaints_list() where subject = ''ZZ Child at risk'''), '1'),
    ('HR is given the ordinary handling action', pg_temp.t_scalar(format('with x as (insert into public.user_capabilities (profile_id, capability, school_id) select %L, ''complaints.handle'', school_id from public.profiles where id = %L returning 1) select count(*)::text from x', u_hr, u_hr)), '1'),
    ('HR now sees ordinary complaints', ((pg_temp.t_val(u_hr, 'select count(*)::text from public.complaints_list() where subject like ''ZZ%'' and category <> ''safeguarding'''))::int >= 3)::text, 'true'),
    ('but not the safeguarding one', pg_temp.t_val(u_hr, 'select count(*)::text from public.complaints_list() where subject = ''ZZ Child at risk'''), '0'),
    ('nor read its thread', pg_temp.t_val(u_hr, 'select count(*)::text from public.complaint_thread(current_setting(''zz.c3'')::uuid)'), '0'),
    ('nor reply to it', (pg_temp.t_val(u_hr, 'select public.handle_reply(current_setting(''zz.c3'')::uuid, ''I should not be able to say this.'', false)') like '42501%')::text, 'true'),
    ('the safeguarding complaint cannot be given to HR', (pg_temp.t_err(u_admin, format('select public.assign_complaint(current_setting(''zz.c3'')::uuid, %L)', u_hr)) = 'CMP01: That person cannot handle this kind of complaint.')::text, 'true'),
    ('HR''s handling action is taken away again', pg_temp.t_scalar(format('with x as (delete from public.user_capabilities where profile_id = %L and capability = ''complaints.handle'' returning 1) select count(*)::text from x', u_hr)), '1'),
    ('and HR sees none again', pg_temp.t_val(u_hr, 'select count(*)::text from public.complaints_list() where subject like ''ZZ%'''), '0'),
