    ('the admin replies to the anonymous complainant', pg_temp.t_try(u_admin, 'select public.handle_reply(current_setting(''zz.c1'')::uuid, ''We will look into the double charge.'', false)'), 'ok:1'),
    ('replying moves it to in review', pg_temp.t_val(u_admin, 'select status from public.complaints_list() where id = current_setting(''zz.c1'')::uuid'), 'in_review'),
    ('the admin adds a private note', pg_temp.t_try(u_admin, 'select public.handle_reply(current_setting(''zz.c1'')::uuid, ''ZZ internal: check the ledger first'', true)'), 'ok:1'),
    ('the complainant sees the reply but not the note', pg_temp.t_val(u_p1, 'select count(*)::text from public.my_complaint_thread(current_setting(''zz.c1'')::uuid)'), '1'),
    ('and the note is not in what they can read', pg_temp.t_val(u_p1, 'select count(*)::text from public.my_complaint_thread(current_setting(''zz.c1'')::uuid) where body like ''ZZ internal%'''), '0'),
    ('handlers see both', pg_temp.t_val(u_admin, 'select count(*)::text from public.complaint_thread(current_setting(''zz.c1'')::uuid)'), '2'),
    ('a handler''s message carries their name', pg_temp.t_val(u_admin, 'select count(*)::text from public.complaint_thread(current_setting(''zz.c1'')::uuid) where from_handler and author_name is not null'), '2'),
    ('the complainant was told about the reply', pg_temp.t_scalar(format('select (count(*) >= 1)::text from public.notifications where profile_id = %L and title = ''The school has replied to your complaint''', u_p1)), 'true'),
    ('another parent cannot read that thread', pg_temp.t_val(u_p2, 'select count(*)::text from public.my_complaint_thread(current_setting(''zz.c1'')::uuid)'), '0'),
    ('nor reply to it', (pg_temp.t_val(u_p2, 'select public.reply_to_complaint(current_setting(''zz.c1'')::uuid, ''I should not be able to say this.'')') like '42501%')::text, 'true'),
    ('a teacher cannot read it as a handler', pg_temp.t_val(u_t1, 'select count(*)::text from public.complaint_thread(current_setting(''zz.c1'')::uuid)'), '0'),
    ('nor reply, change its status, or give it to someone', ((pg_temp.t_val(u_t1, 'select public.handle_reply(current_setting(''zz.c1'')::uuid, ''Not allowed'', false)') like '42501%')::text = 'true' and (pg_temp.t_val(u_t1, 'select public.set_complaint_status(current_setting(''zz.c1'')::uuid, ''closed'')') like '42501%')::text = 'true' and (pg_temp.t_val(u_t1, 'select public.assign_complaint(current_setting(''zz.c1'')::uuid, null)') like '42501%')::text = 'true')::text, 'true'),
    ('a reply cannot be empty', (pg_temp.t_err(u_admin, 'select public.handle_reply(current_setting(''zz.c1'')::uuid, ''   '', false)') = 'CMP01: Write your reply (up to 4000 characters).')::text, 'true'),
    ('the complainant answers', pg_temp.t_try(u_p1, 'select public.reply_to_complaint(current_setting(''zz.c1'')::uuid, ''Thank you. The receipts are attached at the office.'')'), 'ok:1'),
    ('handlers see the answer, with no author name', pg_temp.t_val(u_admin, 'select count(*)::text from public.complaint_thread(current_setting(''zz.c1'')::uuid) where not from_handler and author_name is null'), '1'),
    ('the handlers were told', pg_temp.t_scalar(format('select (count(*) >= 1)::text from public.notifications where profile_id = %L and title = ''A reply to a complaint''', u_admin)), 'true'),
    ('the admin says they are waiting for the complainant', pg_temp.t_try(u_admin, 'select public.set_complaint_status(current_setting(''zz.c1'')::uuid, ''waiting'')'), 'ok:1'),
