    ('a status must be one of the list', (pg_temp.t_err(u_admin, 'select public.set_complaint_status(current_setting(''zz.c1'')::uuid, ''lost'')') = 'CMP01: Choose a status.')::text, 'true'),
    ('the admin resolves it', pg_temp.t_try(u_admin, 'select public.set_complaint_status(current_setting(''zz.c1'')::uuid, ''resolved'')'), 'ok:1'),
    ('the complainant is told', pg_temp.t_scalar(format('select (count(*) >= 1)::text from public.notifications where profile_id = %L and title = ''Your complaint has been resolved''', u_p1)), 'true'),
    ('answering a resolved complaint reopens it', pg_temp.t_try(u_p1, 'select public.reply_to_complaint(current_setting(''zz.c1'')::uuid, ''It happened again this week.'')'), 'ok:1'),
    ('it is open again', pg_temp.t_val(u_admin, 'select status from public.complaints_list() where id = current_setting(''zz.c1'')::uuid'), 'in_review'),
    ('and no longer counts as resolved', pg_temp.t_scalar('select (resolved_at is null)::text from public.complaints where id = current_setting(''zz.c1'')::uuid'), 'true'),
    ('the admin closes it', pg_temp.t_try(u_admin, 'select public.set_complaint_status(current_setting(''zz.c1'')::uuid, ''closed'')'), 'ok:1'),
    ('a closed complaint cannot be answered', (pg_temp.t_err(u_p1, 'select public.reply_to_complaint(current_setting(''zz.c1'')::uuid, ''One more thing'')') = 'CMP01: This complaint is closed. Raise a new one if you still need help.')::text, 'true'),
    ('the complainant sees their own complaints, and only those', pg_temp.t_val(u_p1, 'select count(*)::text from public.my_complaints() where subject like ''ZZ%'''), '2'),
    ('another parent sees only theirs', pg_temp.t_val(u_p2, 'select count(*)::text from public.my_complaints() where subject like ''ZZ%'''), '1'),
    ('a teacher sees only the one they raised', pg_temp.t_val(u_t1, 'select count(*)::text from public.my_complaints() where subject like ''ZZ%'''), '1'),
    ('the history shows what handlers did, without a name for the complainant', pg_temp.t_val(u_admin, 'select (count(*) >= 4)::text from public.complaint_history(current_setting(''zz.c1'')::uuid)'), 'true'),
    ('a teacher cannot read the history', pg_temp.t_val(u_t1, 'select count(*)::text from public.complaint_history(current_setting(''zz.c1'')::uuid)'), '0'),
    ('the admin gives the open complaint to the principal', pg_temp.t_try(u_admin, format('select public.assign_complaint(current_setting(''zz.c2'')::uuid, %L)', u_prin)), 'ok:1'),
    ('it shows who has it', pg_temp.t_val(u_admin, 'select coalesce(assigned_name, ''nobody'') from public.complaints_list() where id = current_setting(''zz.c2'')::uuid'), 'principal'),
    ('it cannot be given to someone who does not handle complaints', (pg_temp.t_err(u_admin, format('select public.assign_complaint(current_setting(''zz.c2'')::uuid, %L)', u_t1)) = 'CMP01: That person cannot handle this kind of complaint.')::text, 'true'),
    ('the admin takes the assignment off', pg_temp.t_try(u_admin, 'select public.assign_complaint(current_setting(''zz.c2'')::uuid, null)'), 'ok:1'),
    ('the choices are the people who handle this kind', pg_temp.t_val(u_admin, 'select (count(*) >= 2)::text from public.complaint_handlers_list(current_setting(''zz.c2'')::uuid)'), 'true'),
    ('the admin cannot reveal who made a complaint', (pg_temp.t_val(u_admin, 'select public.reveal_complaint_submitter(current_setting(''zz.c1'')::uuid, ''A threat was made in this complaint'')') like '42501%')::text, 'true'),
    ('nor the principal', (pg_temp.t_val(u_prin, 'select public.reveal_complaint_submitter(current_setting(''zz.c1'')::uuid, ''A threat was made in this complaint'')') like '42501%')::text, 'true'),
    ('nor HR', (pg_temp.t_val(u_hr, 'select public.reveal_complaint_submitter(current_setting(''zz.c1'')::uuid, ''A threat was made in this complaint'')') like '42501%')::text, 'true'),
    ('nor the complainant themselves through it', (pg_temp.t_val(u_p1, 'select public.reveal_complaint_submitter(current_setting(''zz.c1'')::uuid, ''A threat was made in this complaint'')') like '42501%')::text, 'true'),
    ('the developer needs a reason', (pg_temp.t_err(u_dev, 'select public.reveal_complaint_submitter(current_setting(''zz.c1'')::uuid, ''short'')') = 'CMP01: Give the reason (10 to 500 characters). It is kept in a log.')::text, 'true'),
    ('with a reason, the developer sees who it was', pg_temp.t_val(u_dev, 'select (public.reveal_complaint_submitter(current_setting(''zz.c1'')::uuid, ''A threat was made in this complaint''))->>''name'''), 'parent1'),
    ('and the reveal is logged', pg_temp.t_scalar('select count(*)::text from public.complaint_reveals where complaint_id = current_setting(''zz.c1'')::uuid'), '1'),
    ('the log keeps the reason and never the name', pg_temp.t_scalar('select count(*)::text from public.complaint_reveals r where r.reason ilike ''%parent1%'''), '0'),
    ('the developer can read the log', pg_temp.t_val(u_dev, 'select count(*)::text from public.complaint_reveals_list() where reason = ''A threat was made in this complaint'''), '1'),
    ('the admin cannot', (pg_temp.t_val(u_admin, 'select count(*)::text from public.complaint_reveals_list()') like '42501%')::text, 'true'),
    ('handlers can see in the history that it happened, with the reason', pg_temp.t_val(u_admin, 'select count(*)::text from public.complaint_history(current_setting(''zz.c1'')::uuid) where action = ''revealed the submitter'' and detail = ''A threat was made in this complaint'''), '1'),
    ('but it still shows no name to them afterwards', pg_temp.t_val(u_admin, 'select coalesce(submitter_name, ''none'') from public.complaints_list() where id = current_setting(''zz.c1'')::uuid'), 'none'),
    ('a reveal never writes the name anywhere handlers can read', pg_temp.t_scalar('select count(*)::text from public.complaint_log where detail ilike ''%parent1%'' or action ilike ''%parent1%'''), '0'),
    ('the admin switches complaints off', pg_temp.t_try(u_admin, 'select public.set_school_features((select array_agg(key) from public.app_features where key <> ''complaints''))'), 'ok:1'),
    ('then a parent cannot raise one', (pg_temp.t_val(u_p2, 'select public.submit_complaint(''general'', ''ZZ Off'', ''This should not be possible while it is off.'', false)->>''id''') like '42501%')::text, 'true'),
    ('nor see their complaints', pg_temp.t_val(u_p2, 'select count(*)::text from public.my_complaints()'), '0'),
    ('and the admin sees none', pg_temp.t_val(u_admin, 'select count(*)::text from public.complaints_list() where subject like ''ZZ%'''), '0'),
    ('the admin switches everything back on', pg_temp.t_try(u_admin, 'select public.set_school_features((select array_agg(key) from public.app_features))'), 'ok:1'),
    ('a teacher can raise but not handle', pg_temp.t_try(u_t1, 'select 1 where public.has_capability(''complaints.submit'') and not public.has_capability(''complaints.handle'') and not public.has_capability(''complaints.safeguarding'')'), 'ok:1'),
    ('the head and principal can handle both kinds', pg_temp.t_try(u_admin, 'select 1 where public.has_capability(''complaints.handle'') and public.has_capability(''complaints.safeguarding'') and public.has_capability(''complaints.submit'')'), 'ok:1'),
    ('the principal too', pg_temp.t_try(u_prin, 'select 1 where public.has_capability(''complaints.handle'') and public.has_capability(''complaints.safeguarding'') and public.has_capability(''complaints.submit'')'), 'ok:1'),
    ('HR can only raise', pg_temp.t_try(u_hr, 'select 1 where public.has_capability(''complaints.submit'') and not public.has_capability(''complaints.handle'')'), 'ok:1'),
    -- Payroll
    ('three people are added to the staff', pg_temp.t_scalar(format('with a1 as (insert into public.staff (school_id, full_name, type) values (%L, ''ZZ Pay A'', ''teaching'') returning id), b1 as (insert into public.staff (school_id, full_name, type) values (%L, ''ZZ Pay B'', ''non_teaching'') returning id), c1 as (insert into public.staff (school_id, full_name, type) values (%L, ''ZZ Pay C'', ''non_teaching'') returning id) select (set_config(''zz.pa'', (select id::text from a1), true) is not null and set_config(''zz.pb'', (select id::text from b1), true) is not null and set_config(''zz.pc'', (select id::text from c1), true) is not null and set_config(''zz.t1'', %L, true) is not null)::text', a, a, a, t1)), 'true'),
    ('a teacher cannot set anyone''s pay', (pg_temp.t_val(u_t1, 'select public.save_staff_pay(current_setting(''zz.pa'')::uuid, ''2026-01-01'', 2000, null)::text') like '42501%')::text, 'true'),
    ('nor can the accountant, who sees pay but does not set it', (pg_temp.t_val(u_acc, 'select public.save_staff_pay(current_setting(''zz.pa'')::uuid, ''2026-01-01'', 2000, null)::text') like '42501%')::text, 'true'),
    ('nor the principal', (pg_temp.t_val(u_prin, 'select public.save_staff_pay(current_setting(''zz.pa'')::uuid, ''2026-01-01'', 2000, null)::text') like '42501%')::text, 'true'),
    ('HR sets the first salary for A', pg_temp.t_try(u_hr, 'select public.save_staff_pay(current_setting(''zz.pa'')::uuid, ''2026-01-01'', 2000, ''Joined'')'), 'ok:1'),
    ('and a raise from October', pg_temp.t_try(u_hr, 'select public.save_staff_pay(current_setting(''zz.pa'')::uuid, ''2026-10-01'', 2500, ''Raise'')'), 'ok:1'),
    ('and B''s pay', pg_temp.t_try(u_hr, 'select public.save_staff_pay(current_setting(''zz.pb'')::uuid, ''2026-01-01'', 1000, null)'), 'ok:1'),
    ('and the teacher''s own pay', pg_temp.t_try(u_hr, 'select public.save_staff_pay(current_setting(''zz.t1'')::uuid, ''2026-01-01'', 3000, null)'), 'ok:1'),
    ('the admin can set pay too', pg_temp.t_try(u_admin, 'select public.save_staff_pay(current_setting(''zz.pb'')::uuid, ''2026-01-01'', 1000, null)'), 'ok:1'),
    ('pay cannot be negative', (pg_temp.t_err(u_hr, 'select public.save_staff_pay(current_setting(''zz.pa'')::uuid, ''2026-02-01'', -5, null)') = 'PAY01: Give the basic pay as an amount of zero or more.')::text, 'true'),
    ('a date is needed', (pg_temp.t_err(u_hr, 'select public.save_staff_pay(current_setting(''zz.pa'')::uuid, null, 100, null)') = 'PAY01: Say from which date this pay applies.')::text, 'true'),
    ('only a real member of staff', (pg_temp.t_err(u_hr, 'select public.save_staff_pay(gen_random_uuid(), ''2026-01-01'', 100, null)') = 'PAY01: Choose a member of staff.')::text, 'true'),
    ('the history is newest first', pg_temp.t_val(u_hr, 'select string_agg(basic::text, '','' order by effective_from desc) from public.staff_pay_history(current_setting(''zz.pa'')::uuid)'), '2500.00,2000.00'),
    ('a teacher cannot read it', (pg_temp.t_val(u_t1, 'select count(*)::text from public.staff_pay_history(current_setting(''zz.pa'')::uuid)') = '0')::text, 'true'),
