    ('HR can', pg_temp.t_try(u_hr, 'select 1 from public.staff_pay where basic = 2500'), 'ok:1'),
    ('a parent cannot', pg_temp.t_try(u_p1, 'select 1 from public.staff_pay'), 'ok:0'),
    ('another school cannot', pg_temp.t_try(u_adminb, 'select 1 from public.staff_pay'), 'ok:0'),
    ('the people list shows A''s pay today', pg_temp.t_val(u_hr, 'select basic::text from public.payroll_staff_list() where full_name = ''ZZ Pay A'''), '2500.00'),
