    ('a teacher cannot list people''s pay', (pg_temp.t_val(u_t1, 'select count(*)::text from public.payroll_staff_list()') like '42501%')::text, 'true'),
    ('HR saves A''s bank details', pg_temp.t_try(u_hr, 'select public.save_staff_account(current_setting(''zz.pa'')::uuid, ''GCB'', ''ZZ Pay A'', ''1234567890'', ''C123'', ''P001'')'), 'ok:1'),
    ('the accountant can read them', pg_temp.t_val(u_acc, 'select public.get_staff_account(current_setting(''zz.pa'')::uuid)->>''accountNo'''), '1234567890'),
    ('a teacher cannot', (pg_temp.t_val(u_t1, 'select public.get_staff_account(current_setting(''zz.pa'')::uuid)::text') like '42501%')::text, 'true'),
