    ('and a welfare deduction as a percent of basic', pg_temp.t_try(u_admin, 'insert into public.pay_components (name, kind, calc) values (''ZZ Welfare'', ''deduction'', ''percent_of_basic'')'), 'ok:1'),
    ('and one that is switched off', pg_temp.t_try(u_prin, 'insert into public.pay_components (name, kind, calc, active) values (''ZZ Retired'', ''earning'', ''fixed'', false)'), 'ok:1'),
    ('HR can read them', pg_temp.t_try(u_hr, 'select 1 from public.pay_components where name like ''ZZ%'''), 'ok:3'),
    ('a teacher cannot', pg_temp.t_try(u_t1, 'select 1 from public.pay_components'), 'ok:0'),
    ('HR gives A the transport allowance', pg_temp.t_try(u_hr, 'insert into public.staff_components (staff_id, component_id, amount, effective_from) select current_setting(''zz.pa'')::uuid, id, 150, ''2026-01-01'' from public.pay_components where name = ''ZZ Transport'''), 'ok:1'),
    ('and the welfare deduction at 2 percent', pg_temp.t_try(u_hr, 'insert into public.staff_components (staff_id, component_id, amount, effective_from) select current_setting(''zz.pa'')::uuid, id, 2, ''2026-01-01'' from public.pay_components where name = ''ZZ Welfare'''), 'ok:1'),
    ('and the switched-off one, which should count for nothing', pg_temp.t_try(u_hr, 'insert into public.staff_components (staff_id, component_id, amount, effective_from) select current_setting(''zz.pa'')::uuid, id, 999, ''2026-01-01'' from public.pay_components where name = ''ZZ Retired'''), 'ok:1'),
    ('a teacher cannot give anyone an allowance', pg_temp.t_try(u_t1, 'insert into public.staff_components (staff_id, component_id, amount, effective_from) values (current_setting(''zz.pb'')::uuid, (select id from public.pay_components where name = ''ZZ Transport'' limit 1), 50, ''2026-01-01'')'), 'denied'),
    ('a component in use cannot be deleted', pg_temp.t_try(u_admin, 'delete from public.pay_components where name = ''ZZ Transport'''), 'denied'),
