    ('the accountant adds a bonus for B', pg_temp.t_try(u_acc, 'select public.add_payroll_adjustment(current_setting(''zz.run1'')::uuid, current_setting(''zz.pb'')::uuid, ''ZZ Bonus'', ''earning'', 100, null)'), 'ok:1'),
    ('and an advance to be paid back', pg_temp.t_try(u_acc, 'select public.add_payroll_adjustment(current_setting(''zz.run1'')::uuid, current_setting(''zz.pb'')::uuid, ''ZZ Advance'', ''deduction'', 20, ''From last month'')'), 'ok:1'),
    ('an adjustment needs an amount above zero', (pg_temp.t_err(u_acc, 'select public.add_payroll_adjustment(current_setting(''zz.run1'')::uuid, current_setting(''zz.pb'')::uuid, ''ZZ Zero'', ''earning'', 0, null)') = 'PAY01: Give an amount above zero.')::text, 'true'),
    ('a teacher cannot add one', (pg_temp.t_val(u_t1, 'select public.add_payroll_adjustment(current_setting(''zz.run1'')::uuid, current_setting(''zz.pb'')::uuid, ''ZZ Hack'', ''earning'', 1, null)::text') like '42501%')::text, 'true'),
    ('the accountant calculates', pg_temp.t_val(u_acc, 'select (public.calculate_payroll_run(current_setting(''zz.run1'')::uuid)->>''slips'')::int >= 3'), 'true'),
