    ('A''s basic is the October raise, not the old pay', pg_temp.t_val(u_acc, 'select basic::text from public.payroll_slips where run_id = current_setting(''zz.run1'')::uuid and staff_name = ''ZZ Pay A'''), '2500.00'),
    ('A''s gross adds the transport allowance and not the switched-off one', pg_temp.t_val(u_acc, 'select gross::text from public.payroll_slips where run_id = current_setting(''zz.run1'')::uuid and staff_name = ''ZZ Pay A'''), '2650.00'),
    ('A''s deductions are 2 percent of 2500', pg_temp.t_val(u_acc, 'select deductions::text from public.payroll_slips where run_id = current_setting(''zz.run1'')::uuid and staff_name = ''ZZ Pay A'''), '50.00'),
    ('A''s net pay', pg_temp.t_val(u_acc, 'select net::text from public.payroll_slips where run_id = current_setting(''zz.run1'')::uuid and staff_name = ''ZZ Pay A'''), '2600.00'),
    ('A''s payslip has three lines', pg_temp.t_val(u_acc, 'select count(*)::text from public.payroll_slip_lines l join public.payroll_slips s on s.id = l.slip_id where s.run_id = current_setting(''zz.run1'')::uuid and s.staff_name = ''ZZ Pay A'''), '3'),
    ('B''s gross includes the bonus', pg_temp.t_val(u_acc, 'select gross::text from public.payroll_slips where run_id = current_setting(''zz.run1'')::uuid and staff_name = ''ZZ Pay B'''), '1100.00'),
    ('B''s net is after the advance', pg_temp.t_val(u_acc, 'select net::text from public.payroll_slips where run_id = current_setting(''zz.run1'')::uuid and staff_name = ''ZZ Pay B'''), '1080.00'),
    ('the one-off lines say they are for this month only', pg_temp.t_val(u_acc, 'select count(*)::text from public.payroll_slip_lines l join public.payroll_slips s on s.id = l.slip_id where s.run_id = current_setting(''zz.run1'')::uuid and l.name like ''%(this month only)'''), '2'),
    ('C, with no pay, has no payslip', pg_temp.t_val(u_acc, 'select count(*)::text from public.payroll_slips where run_id = current_setting(''zz.run1'')::uuid and staff_name = ''ZZ Pay C'''), '0'),
    ('the teacher''s slip is their basic only', pg_temp.t_scalar('select net::text from public.payroll_slips where run_id = current_setting(''zz.run1'')::uuid and staff_id = current_setting(''zz.t1'')::uuid'), '3000.00'),
