    ('and 2 percent of that is 40, so the net is 2110', pg_temp.t_val(u_hr, 'select net::text from public.payroll_slips where run_id = current_setting(''zz.run0'')::uuid and staff_name = ''ZZ Pay A'''), '2110.00'),
